((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).el = window.CARDS_BY_LANG.el || {}).place = [{"name":"Πύργος του Άιφελ","emoji":"🗼","meta":["Γαλλία","μεταλλικός πύργος","1889"],"description":"Μεταλλικός πύργος με δικτυωτό σκελετό στο Πεδίο του Άρεως στο Παρίσι, που χτίστηκε για την Παγκόσμια Έκθεση ως προσωρινό κατασκεύασμα και κατέληξε το βασικό σύμβολο της Γαλλίας. Από τα τρία επίπεδα θέασης απλώνεται όλη η πόλη, και τα βράδια ο πύργος αστράφτει με φώτα κάθε ώρα.","fact":"Όσο ο πύργος χτιζόταν, μια ομάδα Παριζιάνων καλλιτεχνών και συγγραφέων διαμαρτυρήθηκε δημόσια εναντίον του, χαρακτηρίζοντάς τον άσχημο και άχρηστο.","wiki_en":"Eiffel Tower"},{"name":"Κολοσσαίο","emoji":"🏟️","meta":["Ιταλία","αρχαίο αμφιθέατρο","1ος αιώνας μ.Χ."],"description":"Το μεγαλύτερο αμφιθέατρο της αρχαίας Ρώμης, όπου γίνονταν μονομαχίες και θεάματα με άγρια ζώα μπροστά σε δεκάδες χιλιάδες θεατές. Παρά τους σεισμούς και τις καταστροφές αιώνων, οι αψίδες και οι καμάρες του παραμένουν ένα από τα πιο αναγνωρίσιμα σύμβολα της Ιταλίας.","fact":"Κάτω από την αρένα σώζεται ένας λαβύρινθος υπόγειων διαδρόμων — το υπόγαιο — όπου κρατούσαν τους μονομάχους και τα ζώα πριν βγουν στον στίβο.","wiki_en":"Colosseum"},{"name":"Άγαλμα της Ελευθερίας","emoji":"🗽","meta":["ΗΠΑ","άγαλμα","1886"],"description":"Γιγαντιαίο άγαλμα μιας γυναίκας με πυρσό, σε ένα νησί του λιμανιού της Νέας Υόρκης, δώρο της Γαλλίας ως σύμβολο φιλίας ανάμεσα στις δύο χώρες. Έγινε σύμβολο ελευθερίας και ελπίδας για τα εκατομμύρια μεταναστών που έφταναν στην Αμερική από τη θάλασσα.","fact":"Το εξωτερικό περίβλημα του αγάλματος είναι φτιαγμένο από λεπτά χάλκινα φύλλα: με τον καιρό οξειδώθηκαν και του έδωσαν το χαρακτηριστικό πρασινωπό χρώμα.","wiki_en":"Statue of Liberty"},{"name":"Σινικό Τείχος","emoji":"🧱","meta":["Κίνα","οχυρωματικό τείχος","αιώνες π.Χ. – 17ος αιώνας"],"description":"Μια αλυσίδα τειχών, πύργων και οχυρών που απλώνεται για χιλιάδες χιλιόμετρα και την έχτιζαν ξανά και ξανά διαφορετικές κινεζικές δυναστείες για να αποκρούουν τις επιδρομές των νομάδων. Σήμερα είναι το μεγαλύτερο ανθρώπινο κατασκεύασμα στον κόσμο και ένα από τα σύμβολα της Κίνας.","fact":"Σε αντίθεση με τον διαδεδομένο μύθο, το τείχος δεν διακρίνεται με γυμνό μάτι από την τροχιά της Γης.","wiki_en":"Great Wall of China"},{"name":"Τατζ Μαχάλ","emoji":"🤍","meta":["Ινδία","μαυσωλείο","17ος αιώνας"],"description":"Μαυσωλείο από λευκό μάρμαρο στην Άγκρα, που έχτισε ο παδισάχ Σαχ Τζαχάν στη μνήμη της αγαπημένης του συζύγου Μουμτάζ Μαχάλ. Οι συμμετρικοί θόλοι, οι μιναρέδες και τα ένθετα ημιπολύτιμα πετράδια θεωρούνται η κορύφωση της αρχιτεκτονικής των Μογγόλων αυτοκρατόρων της Ινδίας.","fact":"Το χρώμα του μαρμάρου του Τατζ Μαχάλ αλλάζει μέσα στη μέρα — από ροδαλό την αυγή έως χρυσαφί στο ηλιοβασίλεμα.","wiki_en":"Taj Mahal"},{"name":"Μάτσου Πίτσου","emoji":"🏔️","meta":["Περού","πόλη των Ίνκας","15ος αιώνας"],"description":"Χαμένη στις Άνδεις ορεινή πόλη των Ίνκας, χτισμένη από πέτρινους όγκους τόσο προσεκτικά προσαρμοσμένους μεταξύ τους που δεν χρειάστηκε κονίαμα. Για πολύ καιρό ήταν άγνωστη στον έξω κόσμο και σώθηκε τόσο καλά ακριβώς επειδή οι Ισπανοί κονκισταδόρες δεν την βρήκαν ποτέ.","fact":"Ο ακριβής προορισμός του Μάτσου Πίτσου παραμένει αντικείμενο συζήτησης: άλλοι το θεωρούν θερινή κατοικία του ηγεμόνα, άλλοι ιερό.","wiki_en":"Machu Picchu"},{"name":"Πυραμίδες της Γκίζας","emoji":"🔺","meta":["Αίγυπτος","αρχαίες πυραμίδες","περίπου 2500 π.Χ."],"description":"Συγκρότημα μνημειακών τάφων των Αιγύπτιων φαραώ στο υψίπεδο δυτικά του Καΐρου, με πιο γνωστή τη Μεγάλη Πυραμίδα του Χέοπα. Για πολλούς αιώνες παρέμενε το ψηλότερο κατασκεύασμα που είχε φτιάξει ποτέ ο άνθρωπος.","fact":"Οι πυραμίδες της Γκίζας είναι το μόνο από τα επτά θαύματα του αρχαίου κόσμου που σώζεται σχεδόν ολόκληρο έως τις μέρες μας.","wiki_en":"Giza pyramid complex"},{"name":"Μεγάλη Σφίγγα της Γκίζας","emoji":"🦁","meta":["Αίγυπτος","άγαλμα με σώμα λιονταριού","περίπου 2500 π.Χ."],"description":"Πελώρια μορφή με σώμα λιονταριού και ανθρώπινο κεφάλι, λαξεμένη σε ασβεστολιθικό βράχο δίπλα στις πυραμίδες της Γκίζας. Θεωρείται ότι το πρόσωπο αποδίδει κάποιον από τους Αιγύπτιους φαραώ, χωρίς όμως οι ειδικοί να συμφωνούν ποιον.","fact":"Η Σφίγγα δεν έχει μύτη, και ένας θρύλος αποδίδει την απώλεια σε κανονιοβολισμό των στρατιωτών του Ναπολέοντα — η ζημιά όμως είναι παλαιότερη από αυτή την ιστορία.","wiki_en":"Great Sphinx of Giza"},{"name":"Πέτρα","emoji":"🏜️","meta":["Ιορδανία","πόλη λαξεμένη στον βράχο","περίπου 4ος αιώνας π.Χ."],"description":"Η αρχαία πρωτεύουσα του ναβαταϊκού βασιλείου, με ναούς και τάφους λαξεμένους μέσα στους ροδοκόκκινους βράχους της ερήμου. Στην πιο διάσημη πρόσοψη, το Αλ Χαζνέ, οδηγεί το στενό φαράγγι Σικ, μήκους περίπου ενός χιλιομέτρου.","fact":"Την Πέτρα την αποκαλούν «ροζ πόλη» για το χαρακτηριστικό χρώμα του αμμόλιθου από τον οποίο είναι λαξεμένες οι προσόψεις της.","wiki_en":"Petra"},{"name":"Χριστός ο Λυτρωτής","emoji":"✝️","meta":["Βραζιλία","άγαλμα","1931"],"description":"Μνημειακό άγαλμα του Ιησού Χριστού με ανοιχτά χέρια στην κορυφή του όρους Κορκοβάντο, πάνω από το Ρίο ντε Ζανέιρο. Φαίνεται σχεδόν από κάθε σημείο της πόλης και έχει γίνει ένα από τα πιο αναγνωρίσιμα σύμβολα της Βραζιλίας.","fact":"Λόγω του ύψους του βουνού, το άγαλμα βρίσκεται συχνά μέσα στα σύννεφα και οι επισκέπτες πρέπει να περιμένουν να διαλυθούν.","wiki_en":"Christ the Redeemer (statue)"},{"name":"Τσιτσέν Ιτσά","emoji":"🐍","meta":["Μεξικό","πόλη των Μάγια","περίπου 9ος αιώνας"],"description":"Μία από τις μεγαλύτερες πόλεις του πολιτισμού των Μάγια στη χερσόνησο του Γιουκατάν, με κέντρο την κλιμακωτή πυραμίδα του Κουκουλκάν. Στις ισημερίες της άνοιξης και του φθινοπώρου, το φως και η σκιά σχηματίζουν στα σκαλιά της ένα φίδι που κατεβαίνει.","fact":"Αν χτυπήσεις παλαμάκια μπροστά στην πυραμίδα του Κουκουλκάν, η ηχώ επιστρέφει σαν την κραυγή του ιερού πουλιού κετσάλ.","wiki_en":"Chichen Itza"},{"name":"Ανγκόρ Βατ","emoji":"🛕","meta":["Καμπότζη","ναϊκό συγκρότημα","12ος αιώνας"],"description":"Το μεγαλύτερο θρησκευτικό συγκρότημα στον κόσμο, που έχτισαν οι Χμερ ηγεμόνες αρχικά ως ινδουιστικό ναό και αργότερα έγινε βουδιστικό ιερό. Οι πέντε πύργοι του, που θυμίζουν μπουμπούκια λωτού, εικονίζονται ακόμη και στη σημαία της Καμπότζης.","fact":"Το Ανγκόρ Βατ περιβάλλεται από τάφρο πλάτους σχεδόν διακοσίων μέτρων, που προστάτευε τον ναό και ταυτόχρονα σταθεροποιούσε τα θεμέλιά του.","wiki_en":"Angkor Wat"},{"name":"Σαγράδα Φαμίλια","emoji":"⛪","meta":["Ισπανία","βασιλική","από το 1882"],"description":"Τεράστια βασιλική στη Βαρκελώνη, σχεδιασμένη από τον αρχιτέκτονα Αντόνι Γκαουντί σε ένα εντελώς προσωπικό ύφος, με πύργους που θυμίζουν λιωμένο κερί και σχήματα από άμμο. Η κατασκευή ξεκίνησε στα τέλη του 19ου αιώνα και δεν έχει ολοκληρωθεί ακόμη.","fact":"Ο Γκαουντί έλεγε ότι ο πελάτης του — ο Θεός — δεν βιάζεται, γι' αυτό και δεν περίμενε να δει το κτίριο τελειωμένο όσο ζούσε.","wiki_en":"Sagrada Família"},{"name":"Μπιγκ Μπεν","emoji":"🕰️","meta":["Ηνωμένο Βασίλειο","πύργος ρολογιού","1859"],"description":"Ο Πύργος της Ελισάβετ στο Παλάτι του Βεστμίνστερ στο Λονδίνο, του οποίου το ρολόι και η μεγάλη καμπάνα είναι από καιρό γνωστά στο κοινό ως Μπιγκ Μπεν. Το χτύπημα αυτού του ρολογιού μεταδίδεται από ραδιόφωνο και τηλεόραση ως ηχητικό σύμβολο της Βρετανίας.","fact":"Αυστηρά μιλώντας, «Μπιγκ Μπεν» δεν είναι το όνομα του πύργου ούτε του ρολογιού, αλλά της μεγαλύτερης καμπάνας μέσα σε αυτόν.","wiki_en":"Big Ben"},{"name":"Γέφυρα του Πύργου","emoji":"🌉","meta":["Ηνωμένο Βασίλειο","ανοιγόμενη γέφυρα","1894"],"description":"Γέφυρα πάνω από τον Τάμεση, δίπλα στον Πύργο του Λονδίνου, με δύο ψηλούς πύργους που ενώνονται με πεζοδιάδρομους. Το κεντρικό τμήμα της ανοίγει για να περάσουν ψηλά πλοία — ένα σπάνιο θέαμα που μαζεύει ακόμη περίεργους.","fact":"Από μακριά η Γέφυρα του Πύργου συγχέεται συχνά με τη Γέφυρα του Λονδίνου, παρόλο που πρόκειται για δύο εντελώς διαφορετικά κατασκευάσματα.","wiki_en":"Tower Bridge"},{"name":"Παλάτι του Μπάκιγχαμ","emoji":"👑","meta":["Ηνωμένο Βασίλειο","βασιλικό παλάτι","από το 1837"],"description":"Η επίσημη κατοικία των Βρετανών μοναρχών στο Λονδίνο, όπου γίνονται οι κρατικές δεξιώσεις και η τελετή της αλλαγής της φρουράς. Όταν ο μονάρχης βρίσκεται μέσα στο παλάτι, στη στέγη υψώνεται το βασιλικό λάβαρο.","fact":"Το παλάτι έχει εκατοντάδες δωμάτια, ανάμεσά τους δική του κινηματογραφική αίθουσα, πισίνα και ταχυδρομείο.","wiki_en":"Buckingham Palace"},{"name":"Στόουνχεντζ","emoji":"🪨","meta":["Ηνωμένο Βασίλειο","μεγαλιθικό μνημείο","περίπου 2500 π.Χ."],"description":"Κύκλος από πελώριους λίθους στην πεδιάδα του Σώλσμπερι στην Αγγλία, που υψώθηκε στους προϊστορικούς χρόνους, πολύ πριν φτάσουν στη Βρετανία τα μεταλλικά εργαλεία. Ο ακριβής προορισμός του μνημείου — ναός, αστεροσκοπείο ή τόπος ταφής — παραμένει αντικείμενο διαφωνιών.","fact":"Μερικοί από τους λίθους του Στόουνχεντζ μεταφέρθηκαν από λόφους της Ουαλίας, δεκάδες χιλιόμετρα μακριά από την πεδιάδα.","wiki_en":"Stonehenge"},{"name":"Λούβρο","emoji":"🖼️","meta":["Γαλλία","μουσείο","άνοιξε το 1793"],"description":"Το μεγαλύτερο μουσείο τέχνης στον κόσμο, στεγασμένο σε παλιό βασιλικό παλάτι στο κέντρο του Παρισιού. Στη συλλογή του φυλάσσεται η «Τζοκόντα» του Λεονάρντο ντα Βίντσι και χιλιάδες άλλα αριστουργήματα από διαφορετικές εποχές.","fact":"Η γυάλινη πυραμίδα στην αυλή του Λούβρου, που έγινε σύμβολο του μουσείου, εμφανίστηκε μόλις στα τέλη του 20ού αιώνα και αρχικά προκάλεσε έντονες διαμάχες.","wiki_en":"Louvre"},{"name":"Παναγία των Παρισίων","emoji":"🔔","meta":["Γαλλία","γοτθικός καθεδρικός ναός","12ος–14ος αιώνας"],"description":"Ο καθεδρικός ναός στο νησί Σιτέ, στο κέντρο του Παρισιού, ένα από τα πρώτα και σημαντικότερα μνημεία της γοτθικής αρχιτεκτονικής στην Ευρώπη. Τον έκανε διάσημο το ομώνυμο μυθιστόρημα του Βίκτωρ Ουγκώ για τον καμπανοκρούστη Κουασιμόδο.","fact":"Μετά την πυρκαγιά του 2019, που κατέστρεψε σοβαρά τη στέγη και το βέλος του, ο ναός αποκαταστάθηκε μέσα σε λίγα χρόνια με ιστορικές τεχνικές.","wiki_en":"Notre-Dame de Paris"},{"name":"Αψίδα του Θριάμβου","emoji":"🏛️","meta":["Γαλλία","θριαμβική αψίδα","1836"],"description":"Μνημειακή αψίδα στην πλατεία Σαρλ ντε Γκωλ στο Παρίσι, που θεμελιώθηκε με διαταγή του Ναπολέοντα προς τιμήν των νικών του γαλλικού στρατού. Από αυτήν ξεκινούν ακτινωτά δώδεκα λεωφόροι, ανάμεσά τους και τα Ηλύσια Πεδία.","fact":"Κάτω από την αψίδα βρίσκεται ο τάφος του Άγνωστου Στρατιώτη με αιώνια φλόγα, που δεν έχει σβήσει από τη δεκαετία του 1920.","wiki_en":"Arc de Triomphe"},{"name":"Βερσαλλίες","emoji":"🪞","meta":["Γαλλία","βασιλικό παλάτι","17ος αιώνας"],"description":"Γιγαντιαίο συγκρότημα παλατιού και κήπων έξω από το Παρίσι, που ο Λουδοβίκος ΙΔ΄ μετέτρεψε από κυνηγετικό πύργο στην κύρια κατοικία των Γάλλων βασιλιάδων. Η Αίθουσα των Κατόπτρων και οι γεωμετρικοί κήποι έγιναν πρότυπο για όλη την Ευρώπη.","fact":"Στην Αίθουσα των Κατόπτρων των Βερσαλλιών υπογράφηκε το 1919 η συνθήκη που έκλεισε επίσημα τον Α΄ Παγκόσμιο Πόλεμο.","wiki_en":"Palace of Versailles"},{"name":"Μον Σαν Μισέλ","emoji":"🏝️","meta":["Γαλλία","νησί-αββαείο","Μεσαίωνας"],"description":"Βραχώδες νησί στις ακτές της Νορμανδίας, στεφανωμένο από μεσαιωνικό αββαείο του οποίου το βέλος φαίνεται από πολλά χιλιόμετρα. Στις μεγάλες παλίρροιες το νερό αποκόπτει το νησί από τη στεριά και το μετατρέπει σε πραγματικό φρούριο.","fact":"Οι παλίρροιες στο Μον Σαν Μισέλ είναι από τις μεγαλύτερες της Ευρώπης και η διαφορά στη στάθμη του νερού φτάνει το ύψος πολυκατοικίας.","wiki_en":"Mont-Saint-Michel"},{"name":"Κεκλιμένος Πύργος της Πίζας","emoji":"📐","meta":["Ιταλία","καμπαναριό","12ος–14ος αιώνας"],"description":"Το ελεύθερο καμπαναριό του καθεδρικού ναού της Πίζας άρχισε να γέρνει ήδη κατά την ανέγερσή του, εξαιτίας του μαλακού εδάφους κάτω από τα θεμέλια. Αυτό ακριβώς το σφάλμα το μετέτρεψε από ένα συνηθισμένο καμπαναριό σε ένα από τα πιο αναγνωρίσιμα αξιοθέατα του κόσμου.","fact":"Κατά καιρούς προσπάθησαν να σταματήσουν την κλίση του πύργου, ακόμη και να τη διορθώσουν λίγο, με υπόγεια αντίβαρα και ενίσχυση των θεμελίων.","wiki_en":"Leaning Tower of Pisa"},{"name":"Φοντάνα ντι Τρέβι","emoji":"🪙","meta":["Ιταλία","κρήνη","1762"],"description":"Η μεγαλύτερη και πιο διάσημη κρήνη της Ρώμης, στολισμένη με γλυπτά θαλάσσιων θεοτήτων μπροστά σε πρόσοψη ανακτόρου. Κατά την παράδοση, οι επισκέπτες ρίχνουν ένα κέρμα στο νερό πάνω από τον ώμο τους για να ξαναγυρίσουν κάποτε στην πόλη.","fact":"Κάθε μέρα μαζεύουν από την κρήνη χιλιάδες κέρματα, και τα χρήματα που συγκεντρώνονται πηγαίνουν σε φιλανθρωπικούς σκοπούς.","wiki_en":"Trevi Fountain"},{"name":"Πάνθεον της Ρώμης","emoji":"🕳️","meta":["Ιταλία","αρχαίος ναός","2ος αιώνας μ.Χ."],"description":"Ένας από τους καλύτερα σωζόμενους ναούς της αρχαίας Ρώμης, με γιγάντιο θόλο που στο κέντρο του αφήνει ένα κυκλικό άνοιγμα, το οπαίο. Από εκεί χύνεται μέσα το φως της μέρας, και όταν βρέχει το νερό κυλά πάνω σε δάπεδο με μελετημένη κλίση.","fact":"Σχεδόν δύο χιλιάδες χρόνια μετά, ο θόλος του Πάνθεον παραμένει ο μεγαλύτερος στον κόσμο από άοπλο σκυρόδεμα.","wiki_en":"Pantheon, Rome"},{"name":"Βασιλική του Αγίου Πέτρου","emoji":"🕊️","meta":["Βατικανό","βασιλική","16ος–17ος αιώνας"],"description":"Ο μεγαλύτερος καθολικός ναός στον κόσμο, χτισμένος στο σημείο όπου κατά την παράδοση θάφτηκε ο απόστολος Πέτρος. Στον θόλο του δούλεψε ο Μιχαήλ Άγγελος, ενώ την πλατεία μπροστά της περιβάλλει η κιονοστοιχία του Μπερνίνι.","fact":"Ο θόλος του Αγίου Πέτρου παραμένει ένας από τους ψηλότερους στον κόσμο, και μπορεί κανείς να ανέβει με τα πόδια από μια στενή εσωτερική σκάλα.","wiki_en":"St. Peter's Basilica"},{"name":"Πομπηία","emoji":"🌋","meta":["Ιταλία","αρχαία πόλη","καταστράφηκε το 79 μ.Χ."],"description":"Ρωμαϊκή πόλη που θάφτηκε κάτω από στάχτη και ελαφρόπετρα στην έκρηξη του Βεζούβιου και γι' αυτό σώθηκε σχεδόν άθικτη έως τις μέρες μας. Οι ανασκαφές αποκάλυψαν δρόμους, σπίτια και τοιχογραφίες που δίνουν μια σπάνια ματιά στην καθημερινή ζωή των αρχαίων Ρωμαίων.","fact":"Τα κενά που άφησαν τα σώματα των θυμάτων στη σκληρυμένη στάχτη τα γεμίζουν οι αρχαιολόγοι με γύψο, παίρνοντας ακριβή εκμαγεία ανθρώπων τη στιγμή της καταστροφής.","wiki_en":"Pompeii"},{"name":"Παρθενώνας","emoji":"🏺","meta":["Ελλάδα","αρχαίος ναός","5ος αιώνας π.Χ."],"description":"Ο κύριος ναός της Ακρόπολης των Αθηνών, αφιερωμένος στη θεά Αθηνά και χτισμένος στην ακμή της κλασικής Ελλάδας. Οι αναλογίες και η κιονοστοιχία του έγιναν το μέτρο σύγκρισης για την αρχιτεκτονική χιλιετίες αργότερα.","fact":"Πολλά γλυπτά και τμήματα της ζωφόρου του Παρθενώνα βρίσκονται σήμερα στο Βρετανικό Μουσείο του Λονδίνου, κάτι που παραμένει παλιά διαφωνία ανάμεσα στην Ελλάδα και τη Βρετανία.","wiki_en":"Parthenon"},{"name":"Αγία Σοφία","emoji":"🕌","meta":["Τουρκία","ναός-τζαμί","6ος αιώνας"],"description":"Επιβλητικό οικοδόμημα στην Κωνσταντινούπολη, που χτίστηκε ως χριστιανικός καθεδρικός ναός, για αιώνες λειτούργησε ως τζαμί, έπειτα ως μουσείο και σήμερα ξανά ως τζαμί. Ο γιγάντιος τρούλος του παρέμεινε για πολύ καιρό ο μεγαλύτερος στον κόσμο.","fact":"Μέσα στο κτίριο μπορεί κανείς να δει ακόμη χριστιανικά ψηφιδωτά και ισλαμική καλλιγραφία να συνυπάρχουν στον ίδιο χώρο.","wiki_en":"Hagia Sophia"},{"name":"Μπλε Τζαμί","emoji":"🔷","meta":["Τουρκία","τζαμί","17ος αιώνας"],"description":"Το τζαμί του σουλτάνου Αχμέτ στην Κωνσταντινούπολη πήρε την ανεπίσημη ονομασία του από τα χιλιάδες μπλε πλακάκια του Ιζνίκ που στολίζουν το εσωτερικό του. Χτίστηκε απέναντι από την Αγία Σοφία και συνομιλεί αρχιτεκτονικά μαζί της.","fact":"Το Μπλε Τζαμί είναι ένα από τα λίγα στον κόσμο που χτίστηκε εξαρχής με έξι μιναρέδες, κάτι που τότε προκάλεσε αντιδράσεις.","wiki_en":"Sultan Ahmed Mosque"},{"name":"Καππαδοκία","emoji":"🎈","meta":["Τουρκία","βραχώδης περιοχή","διαμορφωνόταν εκατομμύρια χρόνια"],"description":"Περιοχή στην κεντρική Τουρκία με παράξενους βραχώδεις σχηματισμούς, τις «καμινάδες των νεράιδων», αλλά και με υπόγειες πόλεις και σπηλαιώδεις ναούς λαξεμένους στον ηφαιστειακό τόφο. Σήμερα είναι γνωστή και για τις πτήσεις με αερόστατο την ώρα της ανατολής.","fact":"Στην Καππαδοκία σώζονται ολόκληρες υπόγειες πόλεις, όπου οι κάτοικοι κρύβονταν από τις επιδρομές σκάβοντας πολυεπίπεδες στοές μέσα στον μαλακό τόφο.","wiki_en":"Cappadocia"},{"name":"Παμούκκαλε","emoji":"⚪","meta":["Τουρκία","ασβεστολιθικές αναβαθμίδες","διαμορφώνονταν για χιλιετίες"],"description":"Κατάλευκες αναβαθμίδες από τραβερτίνη στη νοτιοδυτική Τουρκία, που σχηματίστηκαν από θερμές μεταλλικές πηγές. Το όνομα σημαίνει «βαμβακερό κάστρο» — έτσι μοιάζουν πράγματι τα παγωμένα σκαλοπάτια με το τιρκουάζ νερό.","fact":"Δίπλα στο Παμούκκαλε σώζονται τα ερείπια της αρχαίας Ιεράπολης, της οποίας οι κάτοικοι χρησιμοποιούσαν για αιώνες τις ίδιες θερμές πηγές.","wiki_en":"Pamukkale"},{"name":"Μπουρτζ Χαλίφα","emoji":"🏙️","meta":["ΗΑΕ","ουρανοξύστης","2010"],"description":"Το ψηλότερο κτίριο στον κόσμο, που δεσπόζει πάνω από το Ντουμπάι και φαίνεται από δεκάδες χιλιόμετρα με καθαρό καιρό. Το σχήμα του, που στενεύει προς την κορυφή, είναι εμπνευσμένο από τη σιλουέτα του ερημικού λουλουδιού υμενόκαλλις.","fact":"Στους πάνω ορόφους του Μπουρτζ Χαλίφα το ηλιοβασίλεμα διαρκεί μερικά λεπτά περισσότερο απ' ό,τι στη βάση του κτιρίου.","wiki_en":"Burj Khalifa"},{"name":"Τζαμί του Σεΐχη Ζάγιεντ","emoji":"🕌","meta":["ΗΑΕ","τζαμί","2007"],"description":"Πελώριο κατάλευκο τζαμί στο Άμπου Ντάμπι με δεκάδες θόλους και μιναρέδες, επενδυμένο με μάρμαρο και στολισμένο με ένα από τα μεγαλύτερα χειροποίητα χαλιά στον κόσμο. Πήρε το όνομά του από τον πρώτο πρόεδρο της χώρας και είναι ανοιχτό σε επισκέπτες κάθε θρησκείας.","fact":"Την κύρια αίθουσα προσευχής του τζαμιού στολίζουν γιγαντιαίοι πολυέλαιοι με κρύσταλλα Swarovski, από τους μεγαλύτερους στον κόσμο.","wiki_en":"Sheikh Zayed Grand Mosque"},{"name":"Τείχος των Δακρύων","emoji":"🙏","meta":["Ισραήλ","σωζόμενο τείχος του Όρους του Ναού","αρχαιότητα"],"description":"Το δυτικό τείχος αντιστήριξης του Όρους του Ναού στην Ιερουσαλήμ, ό,τι απέμεινε από το συγκρότημα του Δεύτερου Ναού. Για τους Εβραίους είναι ο πιο ιερός τόπος προσευχής, όπου εδώ και αιώνες έρχονται να θρηνήσουν την καταστροφή του ναού.","fact":"Στις χαραμάδες ανάμεσα στους λίθους του Τείχους των Δακρύων συνηθίζεται να τοποθετούν σημειώματα με προσευχές και αιτήματα προς τον Θεό.","wiki_en":"Western Wall"},{"name":"Τέμενος του Βράχου","emoji":"🟡","meta":["Ισραήλ","ισλαμικό ιερό","7ος αιώνας"],"description":"Ιερό με χρυσό θόλο στο Όρος του Ναού στην Ιερουσαλήμ, ένα από τα αρχαιότερα σωζόμενα μνημεία της ισλαμικής αρχιτεκτονικής. Κατά την παράδοση, από εδώ ανέβηκε στους ουρανούς ο προφήτης Μωάμεθ κατά το νυχτερινό του ταξίδι.","fact":"Η χρυσή επένδυση του θόλου είναι σχετικά πρόσφατη ανανέωση του 20ού αιώνα — αρχικά ο θόλος ήταν καλυμμένος με άλλα υλικά.","wiki_en":"Dome of the Rock"},{"name":"Νεκρά Θάλασσα","emoji":"🧂","meta":["Ισραήλ και Ιορδανία","αλμυρή λίμνη","φυσικός σχηματισμός"],"description":"Κλειστή λίμνη ανάμεσα στο Ισραήλ και την Ιορδανία, με μια από τις υψηλότερες συγκεντρώσεις αλατιού στη Γη: στο νερό της είναι σχεδόν αδύνατο να βυθιστείς, γιατί το σώμα ανεβαίνει μόνο του στην επιφάνεια. Οι ακτές της είναι το χαμηλότερο σημείο στεριάς του πλανήτη.","fact":"Λόγω της έντονης άντλησης νερού, η στάθμη της Νεκρής Θάλασσας πέφτει σταδιακά και η ακτογραμμή υποχωρεί χρόνο με τον χρόνο.","wiki_en":"Dead Sea"},{"name":"Κόκκινη Πλατεία","emoji":"🟥","meta":["Ρωσία","κεντρική πλατεία της Μόσχας","15ος αιώνας"],"description":"Η κεντρική πλατεία της Μόσχας, δίπλα στα τείχη του Κρεμλίνου, που για αιώνες υπήρξε τόπος εμπορίου, παρελάσεων και των μεγάλων ιστορικών στιγμών της χώρας. Το όνομά της είναι πολύ παλαιότερο από τη σοβιετική εποχή: η ρωσική λέξη για το κόκκινο σήμαινε άλλοτε και «ωραίο».","fact":"Η ιστορική ονομασία της πλατείας δεν έχει σχέση ούτε με το χρώμα των τειχών του Κρεμλίνου ούτε με τη σοβιετική συμβολική, σε αντίθεση με τη διαδεδομένη εντύπωση.","wiki_en":"Red Square"},{"name":"Καθεδρικός του Αγίου Βασιλείου","emoji":"🧅","meta":["Ρωσία","καθεδρικός ναός","16ος αιώνας"],"description":"Ο ναός της Σκέπης της Θεοτόκου στην Κόκκινη Πλατεία, χτισμένος με διαταγή του Ιβάν του Τρομερού για την κατάληψη του Καζάν. Οι πολύχρωμοι θόλοι του με τα σχέδια δεν έχουν όμοιό τους και έχουν γίνει από καιρό το οπτικό σύμβολο της Μόσχας.","fact":"Κανένας από τους εννέα θόλους του ναού δεν επαναλαμβάνει το σχέδιο κάποιου άλλου — καθένας είναι ζωγραφισμένος διαφορετικά.","wiki_en":"Saint Basil's Cathedral"},{"name":"Κρεμλίνο της Μόσχας","emoji":"⭐","meta":["Ρωσία","φρούριο και έδρα της εξουσίας","15ος αιώνας"],"description":"Αρχαίο φρούριο στο κέντρο της Μόσχας, με τείχη και πύργους από κόκκινο τούβλο, πίσω από τα οποία βρίσκονται ναοί, ανάκτορα και η κατοικία του Ρώσου προέδρου. Το Κρεμλίνο παραμένει εδώ και αιώνες ενεργό κέντρο της κρατικής εξουσίας.","fact":"Τα ρουμπινένια αστέρια στους πύργους του Κρεμλίνου αντικατέστησαν τους δικέφαλους αετούς μόλις στη δεκαετία του 1930.","wiki_en":"Moscow Kremlin"},{"name":"Ερμιτάζ","emoji":"🎨","meta":["Ρωσία","μουσείο","1764"],"description":"Ένα από τα μεγαλύτερα μουσεία τέχνης στον κόσμο, που απλώνεται στα Χειμερινά Ανάκτορα και στα γειτονικά κτίρια στην προκυμαία του Νέβα, στην Αγία Πετρούπολη. Η συλλογή του ξεκίνησε από την ιδιωτική πινακοθήκη της αυτοκράτειρας Αικατερίνης Β΄.","fact":"Αν ένας επισκέπτης αφιέρωνε έστω ένα λεπτό σε κάθε έκθεμα του Ερμιτάζ, θα χρειαζόταν χρόνια για να δει όλη τη συλλογή.","wiki_en":"Hermitage Museum"},{"name":"Πέτερχοφ","emoji":"⛲","meta":["Ρωσία","συγκρότημα παλατιού και κήπων","18ος αιώνας"],"description":"Εξοχική κατοικία των Ρώσων αυτοκρατόρων κοντά στην Αγία Πετρούπολη, διάσημη για τους καταρράκτες συντριβανιών που λειτουργούν χωρίς ούτε μία αντλία, μόνο με τη φυσική διαφορά ύψους. Τη λένε «ρωσικές Βερσαλλίες», αν και ο Πέτρος Α΄ το σχεδίασε ως αυτοτελές αριστούργημα.","fact":"Στο πάρκο κρύβονται πειραχτικά συντριβάνια: βρέχουν απροειδοποίητα όποιον πατήσει σε κρυμμένη πέτρα ή πλησιάσει υπερβολικά.","wiki_en":"Peterhof Palace"},{"name":"Ναός του Σωτήρος επί του Αίματος","emoji":"🖌️","meta":["Ρωσία","ναός","αρχές 20ού αιώνα"],"description":"Πολυτελής ναός στην Αγία Πετρούπολη, χτισμένος στη μνήμη του αυτοκράτορα Αλεξάνδρου Β΄, στο σημείο όπου τραυματίστηκε θανάσιμα. Οι προσόψεις και οι θόλοι του σε ρωσικό ύφος ξεχωρίζουν έντονα μέσα στη λιτή αρχιτεκτονική του κέντρου, και το εσωτερικό καλύπτεται σχεδόν ολόκληρο από ψηφιδωτά.","fact":"Τα ψηφιδωτά καλύπτουν στο εσωτερικό του ναού αρκετές χιλιάδες τετραγωνικά μέτρα — ένα από τα μεγαλύτερα σύνολα ψηφιδωτού στην Ευρώπη.","wiki_en":"Church of the Savior on Blood"},{"name":"Κίζι","emoji":"🪵","meta":["Ρωσία","μουσείο ξύλινης αρχιτεκτονικής","18ος αιώνας"],"description":"Νησί στη λίμνη Ονέγκα στην Καρελία, γνωστό για το σύνολο των ξύλινων εκκλησιών του, που στήθηκαν χωρίς ούτε ένα καρφί. Η σημαντικότερη, η εκκλησία της Μεταμόρφωσης με τους είκοσι δύο θόλους, είναι η κορύφωση της ρωσικής ξυλουργικής τέχνης.","fact":"Ο θρύλος λέει ότι ο μάστορας που έχτισε την εκκλησία της Μεταμόρφωσης πέταξε το τσεκούρι του στη λίμνη, λέγοντας ότι άλλη τέτοια δεν θα χτίσει κανείς.","wiki_en":"Kizhi Pogost"},{"name":"Λίμνη Βαϊκάλη","emoji":"🌊","meta":["Ρωσία","λίμνη","φυσικός σχηματισμός"],"description":"Η βαθύτερη λίμνη του πλανήτη, στην καρδιά της Σιβηρίας, που κρατά ένα τεράστιο μέρος των παγκόσμιων αποθεμάτων γλυκού νερού. Το νερό της είναι τόσο διάφανο που σε ορισμένα σημεία ο βυθός φαίνεται σε βάθος δεκάδων μέτρων.","fact":"Στη Βαϊκάλη ζει η νέρπα, ένα από τα λίγα είδη φώκιας στον κόσμο που ζουν αποκλειστικά σε γλυκό νερό.","wiki_en":"Lake Baikal"},{"name":"Η Μητέρα Πατρίδα Καλεί","emoji":"⚔️","meta":["Ρωσία","μνημείο","1967"],"description":"Γιγαντιαίο άγαλμα μιας γυναίκας με υψωμένο ξίφος στον λόφο Μαμάγιεφ στο Βόλγκογκραντ, αφιερωμένο στη νίκη στη μάχη του Στάλινγκραντ. Για πολύ καιρό θεωρούνταν το ψηλότερο άγαλμα στον κόσμο.","fact":"Το ξίφος του μνημείου είναι τόσο μεγάλο και τόσο εκτεθειμένο στους ανέμους, που η κατασκευή του ενισχύθηκε αρκετές φορές και άλλαξε το υλικό της λάμας.","wiki_en":"The Motherland Calls"},{"name":"Έλμπρους","emoji":"⛰️","meta":["Ρωσία","βουνό","σβησμένο ηφαίστειο"],"description":"Δικέφαλο βουνό στον Καύκασο, που θεωρείται το ψηλότερο σημείο της Ευρώπης, αν και το σε ποια ήπειρο ανήκει παραμένει αντικείμενο διαφωνίας των γεωγράφων. Είναι σβησμένο ηφαίστειο, με πλαγιές καλυμμένες από παγετώνες όλο τον χρόνο.","fact":"Το Έλμπρους ανήκει στις «Επτά Κορυφές», τα ψηλότερα βουνά κάθε ηπείρου — μια σειρά αναβάσεων δημοφιλής στους ορειβάτες.","wiki_en":"Mount Elbrus"},{"name":"Πύλη του Βρανδεμβούργου","emoji":"🚪","meta":["Γερμανία","θριαμβική πύλη","18ος αιώνας"],"description":"Μνημειακή πύλη στο κέντρο του Βερολίνου, με το άρμα της θεάς της νίκης στην κορυφή, που για δεκαετίες βρισκόταν σχεδόν πάνω στη γραμμή ανάμεσα στο Δυτικό και το Ανατολικό Βερολίνο. Σήμερα είναι σύμβολο της επανένωσης της Γερμανίας και της ειρηνικής πτώσης του Τείχους.","fact":"Στα χρόνια του Ψυχρού Πολέμου η πύλη ήταν πρακτικά αδιάβατη και έγινε ένα από τα πιο αναγνωρίσιμα σύμβολα της διαιρεμένης Γερμανίας.","wiki_en":"Brandenburg Gate"},{"name":"Κάστρο Νοϊσβάνσταϊν","emoji":"🏰","meta":["Γερμανία","κάστρο","19ος αιώνας"],"description":"Παραμυθένιο κάστρο στις βαυαρικές Άλπεις, που χτίστηκε κατά παραγγελία του εκκεντρικού βασιλιά Λουδοβίκου Β΄ ως υλοποίηση των ρομαντικών φαντασιώσεών του. Αυτό ακριβώς το κάστρο ενέπνευσε τους σχεδιαστές της Ντίσνεϊ για το διάσημο κάστρο της Ωραίας Κοιμωμένης.","fact":"Ο Λουδοβίκος Β΄ έζησε στο κάστρο μόνο λίγους μήνες πριν τον μυστηριώδη θάνατό του και δεν το είδε ποτέ εντελώς τελειωμένο.","wiki_en":"Neuschwanstein Castle"},{"name":"Καθεδρικός της Κολωνίας","emoji":"⛪","meta":["Γερμανία","γοτθικός καθεδρικός ναός","από τον 13ο αιώνα"],"description":"Ένας από τους ψηλότερους γοτθικούς καθεδρικούς ναούς της Ευρώπης, με διάτρητα βέλη που δεσπόζουν πάνω από το κέντρο της Κολωνίας. Η ανέγερσή του κράτησε αιώνες και σταμάτησε για μεγάλο διάστημα, προτού συνεχιστεί και ολοκληρωθεί τον 19ο αιώνα.","fact":"Ο ναός άντεξε στους βομβαρδισμούς του Β΄ Παγκοσμίου Πολέμου, αν και υπέστη ζημιές, ενώ το κέντρο της Κολωνίας γύρω του καταστράφηκε σχεδόν ολοκληρωτικά.","wiki_en":"Cologne Cathedral"},{"name":"Γέφυρα του Καρόλου","emoji":"🚶","meta":["Τσεχία","γέφυρα","14ος αιώνας"],"description":"Παλιά πέτρινη γέφυρα πάνω από τον Μολδάβα στην Πράγα, στολισμένη με μια σειρά αγαλμάτων αγίων, που οδηγεί από την Παλιά Πόλη προς το Κάστρο της Πράγας. Μέρα και νύχτα παραμένει ένα από τα πιο πολυσύχναστα πεζά σημεία της πρωτεύουσας.","fact":"Ο θρύλος λέει ότι στο κονίαμα της γέφυρας πρόσθεταν κρόκους αυγών, για να γίνει η κατασκευή πιο γερή.","wiki_en":"Charles Bridge"},{"name":"Παλάτι Σένμπρουν","emoji":"🌳","meta":["Αυστρία","αυτοκρατορικό παλάτι","18ος αιώνας"],"description":"Θερινή κατοικία των Αυστριακών Αψβούργων στη Βιέννη, με πολυτελή εσωτερικά και γεωμετρικό πάρκο που περιλαμβάνει έναν από τους παλαιότερους ζωολογικούς κήπους στον κόσμο. Εδώ πέρασε τα παιδικά της χρόνια η Μαρία Αντουανέτα και εδώ έπαιξε ο μικρός Μότσαρτ μπροστά στην αυτοκράτειρα.","fact":"Ο ζωολογικός κήπος στον χώρο του Σένμπρουν ιδρύθηκε ήδη τον 18ο αιώνα και θεωρείται ο παλαιότερος που λειτουργεί αδιάκοπα στον κόσμο.","wiki_en":"Schönbrunn Palace"},{"name":"Αλάμπρα","emoji":"🔶","meta":["Ισπανία","συγκρότημα παλατιού και φρουρίου","13ος–14ος αιώνας"],"description":"Μαυριτανικό φρούριο και ανακτορικό συγκρότημα στον λόφο πάνω από τη Γρανάδα, που έχτισε η τελευταία μουσουλμανική δυναστεία της Ιβηρικής χερσονήσου. Οι σκαλιστές αψίδες, τα πλακάκια και οι ήσυχες αυλές με τα συντριβάνια θεωρούνται η κορύφωση της ισλαμικής τέχνης στην Ευρώπη.","fact":"Μετά την πτώση της Γρανάδας το 1492 η Αλάμπρα πέρασε στους Ισπανούς βασιλιάδες, και αργότερα μέρος του συγκροτήματος έγινε το αναγεννησιακό παλάτι του Καρόλου Ε΄.","wiki_en":"Alhambra"},{"name":"Πάρκο Γκουέλ","emoji":"🦎","meta":["Ισπανία","πάρκο","αρχές 20ού αιώνα"],"description":"Ιδιόρρυθμο πάρκο στη Βαρκελώνη, σχεδιασμένο από τον Αντόνι Γκαουντί, με φιδωτά παγκάκια, ψηφιδωτές βεράντες και παραμυθένια σπιτάκια στην είσοδο. Αρχικά είχε σχεδιαστεί ως αριστοκρατική συνοικία κατοικιών, αλλά η ιδέα δεν έπιασε και ο χώρος έγινε δημόσιο πάρκο.","fact":"Η ψηφιδωτή σαύρα στην κύρια είσοδο του πάρκου έχει γίνει ένα από τα πιο αναγνωρίσιμα και πολυφωτογραφημένα σύμβολα της Βαρκελώνης.","wiki_en":"Park Güell"},{"name":"Ματερχορν","emoji":"🍫","meta":["Ελβετία και Ιταλία","βουνό","φυσικός σχηματισμός"],"description":"Ένα από τα πιο αναγνωρίσιμα βουνά των Άλπεων, με σχεδόν συμμετρική πυραμιδική κορυφή στα σύνορα της Ελβετίας και της Ιταλίας. Αυτό ακριβώς το σχήμα ενέπνευσε το λογότυπο της σοκολάτας Toblerone.","fact":"Η πρώτη επιτυχημένη ανάβαση στο Ματερχορν τον 19ο αιώνα κατέληξε σε τραγωδία: στην κατάβαση σκοτώθηκε μέρος της αποστολής.","wiki_en":"Matterhorn"},{"name":"Φιόρδ Γκέιρανγκερ","emoji":"⛴️","meta":["Νορβηγία","φιόρδ","φυσικός σχηματισμός"],"description":"Ένα από τα πιο γραφικά φιόρδ της Νορβηγίας, περιτριγυρισμένο από κατακόρυφους βράχους με πολλούς καταρράκτες, ανάμεσά τους και ο διάσημος καταρράκτης «Επτά Αδελφές». Το καλοκαίρι μπαίνουν εδώ τεράστια κρουαζιερόπλοια, που ελίσσονται ανάμεσα στις στενές ακτές.","fact":"Το φιόρδ σχηματίστηκε από την κίνηση των παγετώνων, που άφησαν πίσω τους μια βαθιά, φιδωτή κοιλάδα — αργότερα την πλημμύρισε η θάλασσα.","wiki_en":"Geirangerfjord"},{"name":"Βράχοι του Μόχερ","emoji":"🐦","meta":["Ιρλανδία","παράκτιοι βράχοι","φυσικός σχηματισμός"],"description":"Κατακόρυφοι βράχοι στη δυτική ακτή της Ιρλανδίας, που πέφτουν στον Ατλαντικό από ύψος πάνω από διακόσια μέτρα. Με καλό καιρό διακρίνονται από εδώ τα νησιά Άραν και τα βουνά των γειτονικών κομητειών.","fact":"Στα πρανή των βράχων του Μόχερ φωλιάζουν χιλιάδες θαλασσοπούλια, ανάμεσά τους και αποικίες θαλασσοπαπαγάλων, μικρών πουλιών με έντονο ράμφος.","wiki_en":"Cliffs of Moher"},{"name":"Κάστρο του Εδιμβούργου","emoji":"🛡️","meta":["Ηνωμένο Βασίλειο","φρούριο","Μεσαίωνας"],"description":"Μεσαιωνικό φρούριο στην κορυφή ενός σβησμένου ηφαιστείου, στο κέντρο του Εδιμβούργου, που για αιώνες υπήρξε βασιλική κατοικία και στρατιωτικό οχυρό. Εδώ φυλάσσονται τα βασιλικά διάσημα της Σκωτίας, και από τα τείχη ρίχνει ακόμη κανόνι, με το οποίο οι κάτοικοι ρύθμιζαν τα ρολόγια τους.","fact":"Κάθε μέρα εκτός Κυριακής, στη μία ακριβώς το μεσημέρι, ρίχνει από το κάστρο ένα κανόνι — παράδοση που ξεκίνησε για τους ναυτικούς στο λιμάνι.","wiki_en":"Edinburgh Castle"},{"name":"Λοχ Νες","emoji":"🦕","meta":["Ηνωμένο Βασίλειο","λίμνη","φυσικός σχηματισμός"],"description":"Μακριά και στενή λίμνη στα Υψίπεδα της Σκωτίας, διάσημη για τον θρύλο του μυστηριώδους τέρατος Νέσι, που υποτίθεται ζει στα σκοτεινά νερά της. Παρά τις δεκαετίες αναζητήσεων και αποστολών, επιστημονικές αποδείξεις για την ύπαρξη του τέρατος δεν βρέθηκαν ποτέ.","fact":"Λόγω της μεγάλης ποσότητας τύρφης, το νερό στο Λοχ Νες είναι πολύ σκούρο, κάτι που δυσκολεύει πολύ κάθε υποβρύχια παρατήρηση.","wiki_en":"Loch Ness"},{"name":"Γέφυρα Γκόλντεν Γκέιτ","emoji":"🌁","meta":["ΗΠΑ","κρεμαστή γέφυρα","1937"],"description":"Έντονα πορτοκαλί κρεμαστή γέφυρα πάνω από το στενό στην είσοδο του κόλπου του Σαν Φρανσίσκο, που για πολύ καιρό ήταν η μεγαλύτερη κρεμαστή γέφυρα στον κόσμο. Συχνά χάνεται μέσα σε πυκνή ομίχλη, κάτι που την κάνει ακόμη πιο αναγνωρίσιμη.","fact":"Το χρώμα της γέφυρας ονομάζεται επίσημα «διεθνές πορτοκαλί» και επιλέχθηκε εν μέρει επειδή ξεχωρίζει καλά μέσα στην ομίχλη.","wiki_en":"Golden Gate Bridge"},{"name":"Επιγραφή του Χόλιγουντ","emoji":"🎬","meta":["ΗΠΑ","επιγραφή σε πλαγιά λόφου","1923"],"description":"Τεράστια λευκά γράμματα στον λόφο πάνω από το Λος Άντζελες, που στήθηκαν αρχικά ως διαφήμιση μιας οικιστικής περιοχής και αργότερα έγιναν σύμβολο όλης της αμερικανικής κινηματογραφικής βιομηχανίας. Κάθε γράμμα έχει ύψος πολλών ορόφων και φαίνεται από πολλές συνοικίες της πόλης.","fact":"Αρχικά η επιγραφή έγραφε «HOLLYWOODLAND» — τα τέσσερα τελευταία γράμματα αφαιρέθηκαν μόλις μετά από κάποιες δεκαετίες.","wiki_en":"Hollywood Sign"},{"name":"Γκραντ Κάνιον","emoji":"🏜️","meta":["ΗΠΑ","φαράγγι","διαμορφωνόταν εκατομμύρια χρόνια"],"description":"Πελώριο φαράγγι που χάραξε ο ποταμός Κολοράντο σε ένα υψίπεδο στα νοτιοδυτικά των ΗΠΑ, αποκαλύπτοντας στρώματα πετρωμάτων ηλικίας εκατοντάδων εκατομμυρίων ετών. Οι διαστάσεις του είναι τόσο μεγάλες που η αντικρινή πλευρά μόλις διακρίνεται μέσα στην αχλή.","fact":"Τα στρώματα των πολύχρωμων πετρωμάτων στα τοιχώματα του φαραγγιού επιτρέπουν στους γεωλόγους να διαβάζουν την ιστορία της Γης σαν σελίδες βιβλίου.","wiki_en":"Grand Canyon"},{"name":"Γέλοουστοουν","emoji":"♨️","meta":["ΗΠΑ","εθνικό πάρκο","1872"],"description":"Το πρώτο εθνικό πάρκο στον κόσμο, διάσημο για τους θερμοπίδακες, τις θερμές πηγές και το υπερηφαίστειο που κοιμάται κάτω από την έκτασή του. Ο πιο γνωστός θερμοπίδακας του πάρκου, ο Old Faithful, εκτοξεύεται με αρκετά προβλέψιμη κανονικότητα.","fact":"Κάτω από το Γέλοουστοουν βρίσκεται ένα από τα μεγαλύτερα ενεργά υπερηφαίστεια του πλανήτη, αν και οι επιστήμονες δεν αναμένουν έκρηξη στο ορατό μέλλον.","wiki_en":"Yellowstone National Park"},{"name":"Καταρράκτες του Νιαγάρα","emoji":"💦","meta":["ΗΠΑ και Καναδάς","καταρράκτης","φυσικός σχηματισμός"],"description":"Σύστημα τριών ορμητικών καταρρακτών στα σύνορα των ΗΠΑ και του Καναδά, με πιο γνωστό το «Πέταλο», τον μεγαλύτερο σε όγκο πίπτοντος νερού. Τη νύχτα τους φωτίζουν με χρωματιστούς προβολείς, και το καλοκαίρι κυκλοφορούν κάτω από αυτούς πλοιάρια περιήγησης.","fact":"Ο πρώτος άνθρωπος που επέζησε από πτώση στους καταρράκτες του Νιαγάρα μέσα σε βαρέλι ήταν μια ηλικιωμένη δασκάλα, στις αρχές του 20ού αιώνα.","wiki_en":"Niagara Falls"},{"name":"Όρος Ράσμορ","emoji":"🪨","meta":["ΗΠΑ","γλυπτό μνημείο","1941"],"description":"Γρανιτένιος βράχος στη Νότια Ντακότα, στον οποίο είναι λαξεμένα τα πελώρια πρόσωπα τεσσάρων Αμερικανών προέδρων — του Ουάσιγκτον, του Τζέφερσον, του Ρούζβελτ και του Λίνκολν. Στο μνημείο δούλεψαν πάνω από δέκα χρόνια εκατοντάδες εργάτες, κρεμασμένοι σε εξέδρες με συρματόσχοινα.","fact":"Αρχικά σχεδιαζόταν να απεικονιστούν οι πρόεδροι μέχρι τη μέση, αλλά το έργο περιορίστηκε μόνο στα πρόσωπα λόγω έλλειψης χρημάτων.","wiki_en":"Mount Rushmore"},{"name":"Εμπάιρ Στέιτ Μπίλντινγκ","emoji":"🦍","meta":["ΗΠΑ","ουρανοξύστης","1931"],"description":"Ουρανοξύστης σε στιλ αρ ντεκό στο Μανχάταν, που για δεκαετίες παρέμενε το ψηλότερο κτίριο στον κόσμο. Τα επίπεδα θέασης στους πάνω ορόφους του παραμένουν και σήμερα ένα από τα πιο δημοφιλή σημεία για να δει κανείς τη Νέα Υόρκη από ψηλά.","fact":"Πάνω στην κορυφή του Εμπάιρ Στέιτ Μπίλντινγκ κρατιόταν ο Κινγκ Κονγκ στη διάσημη ταινία του 1933.","wiki_en":"Empire State Building"},{"name":"Τάιμς Σκουέρ","emoji":"🎇","meta":["ΗΠΑ","πλατεία","αρχές 20ού αιώνα"],"description":"Πολυσύχναστο σταυροδρόμι στο Μανχάταν, γεμάτο γιγαντιαίες φωτεινές διαφημιστικές οθόνες και περιτριγυρισμένο από τα θέατρα του Μπρόντγουεϊ. Κάθε χρόνο χιλιάδες άνθρωποι υποδέχονται εδώ το νέο έτος, παρακολουθώντας την κατάβαση της φωτεινής σφαίρας.","fact":"Η πλατεία πήρε το όνομά της από την εφημερίδα The New York Times, της οποίας τα γραφεία βρισκόταν κάποτε σε κτίριο στο σημείο αυτό.","wiki_en":"Times Square"},{"name":"Σέντραλ Παρκ","emoji":"🍂","meta":["ΗΠΑ","αστικό πάρκο","1858"],"description":"Τεράστιο πράσινο ορθογώνιο μέσα στην πυκνή δόμηση του Μανχάταν, σχεδιασμένο ως τόπος ξεκούρασης για τους κατοίκους μιας μεγαλούπολης που μεγάλωνε ραγδαία. Έχει λίμνες, λιβάδια, ζωολογικό κήπο και δεκάδες σημεία γνωστά από δεκάδες ταινίες του Χόλιγουντ.","fact":"Το Σέντραλ Παρκ ήταν ένα από τα πρώτα μεγάλα πάρκα που σχεδιάστηκαν εξαρχής, αντί να αναπτυχθούν γύρω από ένα υπάρχον φυσικό τοπίο.","wiki_en":"Central Park"},{"name":"Γέφυρα του Μπρούκλιν","emoji":"🚴","meta":["ΗΠΑ","κρεμαστή γέφυρα","1883"],"description":"Μία από τις παλαιότερες κρεμαστές γέφυρες της Αμερικής, που ενώνει το Μανχάταν με το Μπρούκλιν πάνω από τον Ιστ Ρίβερ. Οι πέτρινοι νεογοτθικοί πύργοι της και ο ιστός από χαλύβδινα καλώδια θεωρήθηκαν την εποχή της κατασκευής μηχανικό θαύμα.","fact":"Η κατασκευή της γέφυρας κράτησε πάνω από δέκα χρόνια και κόστισε τη ζωή σε αρκετές δεκάδες εργάτες, ανάμεσά τους και στον μηχανικό του έργου.","wiki_en":"Brooklyn Bridge"},{"name":"Λευκός Οίκος","emoji":"🦅","meta":["ΗΠΑ","κατοικία του προέδρου","1800"],"description":"Η επίσημη κατοικία και ο χώρος εργασίας του προέδρου των ΗΠΑ στην Ουάσιγκτον, αναγνωρίσιμη από τη λευκή νεοκλασική πρόσοψη. Το κτίριο ανακατασκευάστηκε αρκετές φορές μετά την πυρκαγιά στον πόλεμο του 1812, διατήρησε όμως την ιστορική μορφή και το όνομά του.","fact":"Η ονομασία «Λευκός Οίκος» καθιερώθηκε επίσημα μόλις στις αρχές του 20ού αιώνα, παρόλο που ανεπίσημα τον έλεγαν έτσι πολύ πιο πριν.","wiki_en":"White House"},{"name":"Στριπ του Λας Βέγκας","emoji":"🎰","meta":["ΗΠΑ","δρόμος με καζίνο και ξενοδοχεία","20ός αιώνας"],"description":"Το διάσημο τμήμα της λεωφόρου στο Λας Βέγκας, γεμάτο πελώρια ξενοδοχεία-καζίνο με θεματική διακόσμηση — από αιγυπτιακές πυραμίδες μέχρι βενετσιάνικα κανάλια. Τη νύχτα ο δρόμος γίνεται μια θάλασσα από νέον, που έχει γίνει η ταυτότητα της πόλης.","fact":"Πολλά από τα διάσημα ξενοδοχεία του Στριπ γκρεμίστηκαν και ξαναχτίστηκαν αρκετές φορές, για να εντυπωσιάσουν το κοινό με ακόμη πιο μεγαλειώδη θεάματα.","wiki_en":"Las Vegas Strip"},{"name":"Κοιλάδα των Μνημείων","emoji":"🌵","meta":["ΗΠΑ","υψίπεδο με βραχώδεις όγκους","διαμορφωνόταν εκατομμύρια χρόνια"],"description":"Ερημικό υψίπεδο στα σύνορα της Αριζόνα και της Γιούτα, γνωστό για τις σιλουέτες των γιγάντιων όγκων από αμμόλιθο, που ο άνεμος και το νερό έπλασαν σε εκατομμύρια χρόνια. Τα τοπία αυτά είναι γνωστά από δεκάδες γουέστερν και διαφημιστικά.","fact":"Η Κοιλάδα των Μνημείων βρίσκεται μέσα στην περιοχή των ιθαγενών Ναβάχο και τη διαχειρίζονται οι ίδιοι οι Ναβάχο, όχι η υπηρεσία εθνικών πάρκων των ΗΠΑ.","wiki_en":"Monument Valley"},{"name":"Αλκατράζ","emoji":"⛓️","meta":["ΗΠΑ","παλιά φυλακή σε νησί","έκλεισε το 1963"],"description":"Βραχώδες νησί στον κόλπο του Σαν Φρανσίσκο, όπου για δεκαετίες λειτουργούσε ομοσπονδιακή φυλακή αυστηρής ασφαλείας για τους πιο επικίνδυνους κρατούμενους. Θεωρούνταν ότι τα κρύα ρεύματα γύρω από το νησί καθιστούσαν την απόδραση σχεδόν αδύνατη.","fact":"Καμία επίσημα επιβεβαιωμένη απόδραση από το Αλκατράζ δεν πέτυχε, αν και η τύχη κάποιων δραπετών δεν εξακριβώθηκε ποτέ.","wiki_en":"Alcatraz Island"},{"name":"Πύργος CN","emoji":"🗼","meta":["Καναδάς","τηλεπικοινωνιακός πύργος","1976"],"description":"Ψηλός τηλεπικοινωνιακός πύργος στο κέντρο του Τορόντο, που για πολύ καιρό θεωρούνταν το ψηλότερο ελεύθερο κατασκεύασμα στον κόσμο. Σε ένα από τα ανώτερα επίπεδά του έχει εξέδρα θέασης με γυάλινο δάπεδο.","fact":"Πατώντας στο γυάλινο δάπεδο της εξέδρας βλέπεις τον δρόμο πολύ χαμηλά — πολλοί επισκέπτες δεν τολμούν να ανέβουν πάνω του αμέσως.","wiki_en":"CN Tower"},{"name":"Καταρράκτες Ιγκουασού","emoji":"🦋","meta":["Αργεντινή και Βραζιλία","σύστημα καταρρακτών","φυσικός σχηματισμός"],"description":"Καταρράκτης από αρκετές εκατοντάδες ξεχωριστούς καταρράκτες στα σύνορα της Αργεντινής και της Βραζιλίας, που απλώνεται για χιλιόμετρα κατά μήκος του ποταμού. Το κεντρικό και ορμητικότερο τμήμα του συστήματος λέγεται «Λαρύγγι του Διαβόλου».","fact":"Οι καταρράκτες Ιγκουασού είναι πιο πλατείς και κατά κάποιον τρόπο πιο επιβλητικοί από τους διάσημους καταρράκτες του Νιαγάρα στη Βόρεια Αμερική.","wiki_en":"Iguazu Falls"},{"name":"Καταρράκτης Άνχελ","emoji":"💧","meta":["Βενεζουέλα","καταρράκτης","φυσικός σχηματισμός"],"description":"Ο ψηλότερος αδιάκοπος καταρράκτης στον κόσμο, που πέφτει από την επίπεδη κορυφή ενός τραπεζοειδούς βουνού μέσα στη ζούγκλα της Βενεζουέλας. Το νερό πέφτει από τόσο ύψος που μέρος του γίνεται ομίχλη πριν φτάσει στο έδαφος.","fact":"Ο καταρράκτης πήρε το όνομά του από τον Αμερικανό πιλότο Τζίμι Έιντζελ, που ήταν από τους πρώτους που πέταξαν πάνω από αυτόν και τον έκαναν γνωστό.","wiki_en":"Angel Falls"},{"name":"Νησιά Γκαλαπάγκος","emoji":"🐢","meta":["Ισημερινός","ηφαιστειογενές αρχιπέλαγος","φυσικός σχηματισμός"],"description":"Απομονωμένο αρχιπέλαγος στον Ειρηνικό, του οποίου η μοναδική πανίδα — γιγάντιες χελώνες, ιγκουάνα και σπίνοι — οδήγησε τον Κάρολο Δαρβίνο στις σκέψεις που αργότερα έγιναν η θεωρία της εξέλιξης. Πολλά είδη εδώ δεν συναντώνται πουθενά αλλού στη Γη.","fact":"Ορισμένες γιγάντιες χελώνες των Γκαλαπάγκος ζουν πάνω από εκατό χρόνια και μπορούν να περάσουν εβδομάδες χωρίς φαγητό και νερό.","wiki_en":"Galápagos Islands"},{"name":"Νήσος του Πάσχα","emoji":"🗿","meta":["Χιλή","νησί με πέτρινα αγάλματα","περίπου 13ος–16ος αιώνας"],"description":"Μικροσκοπικό νησί στον Ειρηνικό, διάσημο για τα εκατοντάδες πελώρια πέτρινα αγάλματα μοάι, που λάξευσαν οι αρχαίοι Πολυνήσιοι κάτοικοί του. Πώς ακριβώς μετακινούσαν τις πολύτονες μορφές στο νησί χωρίς σύγχρονα μηχανήματα δεν έχει εξακριβωθεί πλήρως.","fact":"Τα περισσότερα αγάλματα μοάι έχουν δυσανάλογα μεγάλα κεφάλια και σώματα μισοχωμένα στη γη, γι' αυτό και για καιρό τα θεωρούσαν χωρίς πόδια.","wiki_en":"Easter Island"},{"name":"Σαλάρ ντε Ουγιούνι","emoji":"🪞","meta":["Βολιβία","αλατούχος έρημος","φυσικός σχηματισμός"],"description":"Το μεγαλύτερο αλατούχο υψίπεδο στον κόσμο, που έμεινε στη θέση μιας αρχαίας λίμνης που στέρεψε, ψηλά στις Άνδεις της Βολιβίας. Μετά τις βροχές, ένα λεπτό στρώμα νερού μετατρέπει την επιφάνεια σε γιγαντιαίο καθρέφτη που αντανακλά τον ουρανό.","fact":"Κάτω από την εκτυφλωτικά λευκή κρούστα αλατιού του Ουγιούνι κρύβονται τεράστια αποθέματα λιθίου, βασικής πρώτης ύλης για τις σύγχρονες μπαταρίες.","wiki_en":"Salar de Uyuni"},{"name":"Όπερα του Σίδνεϊ","emoji":"⛵","meta":["Αυστραλία","θέατρο","1973"],"description":"Συγκρότημα συναυλιών και θεάτρου στην ακτή του λιμανιού του Σίδνεϊ, του οποίου η στέγη από λευκά καμπυλωτά «πανιά» έγινε το βασικό σύμβολο της Αυστραλίας. Το ασυνήθιστο σχήμα του κτιρίου έκανε την κατασκευή πολύ πιο αργή και δύσκολη απ' ό,τι είχε αρχικά σχεδιαστεί.","fact":"Ο δημιουργός του σχεδίου, ο Δανός αρχιτέκτονας Γιορν Ούτσον, έφυγε από την Αυστραλία μετά από διαφωνίες πριν ολοκληρωθεί το έργο και δεν είδε ποτέ το κτίριο με τα μάτια του.","wiki_en":"Sydney Opera House"},{"name":"Μεγάλος Κοραλλιογενής Ύφαλος","emoji":"🐠","meta":["Αυστραλία","κοραλλιογενής ύφαλος","φυσικός σχηματισμός"],"description":"Το μεγαλύτερο σύστημα κοραλλιογενών υφάλων στον κόσμο, που απλώνεται για χιλιάδες χιλιόμετρα κατά μήκος της βορειοανατολικής ακτής της Αυστραλίας. Είναι τόσο μεγάλο που ορισμένα τμήματά του διακρίνονται ακόμη και από το διάστημα.","fact":"Λόγω της θέρμανσης του ωκεανού και της λεύκανσης των κοραλλιών, μεγάλο μέρος του υφάλου απειλείται — έγινε σύμβολο της ευθραυστότητας των θαλάσσιων οικοσυστημάτων.","wiki_en":"Great Barrier Reef"},{"name":"Ουλουρού","emoji":"🟠","meta":["Αυστραλία","μονολιθικός βράχος","φυσικός σχηματισμός"],"description":"Γιγαντιαίος βράχος από αμμόλιθο στη μέση της αυστραλιανής ερήμου, ιερός για τους ιθαγενείς Ανάνγκου της περιοχής. Ανάλογα με την ώρα της μέρας και τον καιρό, η επιφάνειά του αλλάζει χρώμα από ώχρα και καφέ έως έντονο κόκκινο.","fact":"Παλιότερα η ανάβαση στον βράχο ήταν δημοφιλής στους τουρίστες, σήμερα όμως απαγορεύεται εντελώς, από σεβασμό στις παραδόσεις των ιθαγενών.","wiki_en":"Uluru"},{"name":"Όρος Φούτζι","emoji":"🗻","meta":["Ιαπωνία","ηφαίστειο","φυσικός σχηματισμός"],"description":"Ο συμμετρικός κώνος ενός κοιμισμένου ηφαιστείου, το ψηλότερο βουνό της Ιαπωνίας και ένα από τα βασικά εθνικά σύμβολα της χώρας. Η σιλουέτα του έχει απεικονιστεί αμέτρητες φορές σε ιαπωνικά χαρακτικά και στη ζωγραφική.","fact":"Το όρος Φούτζι θεωρείται ενεργό, έστω και κοιμισμένο ηφαίστειο — η τελευταία γνωστή έκρηξη έγινε στις αρχές του 18ου αιώνα.","wiki_en":"Mount Fuji"},{"name":"Φουσίμι Ινάρι","emoji":"⛩️","meta":["Ιαπωνία","ιερό του σιντοϊσμού","ιδρύθηκε τον 8ο αιώνα"],"description":"Ιερό στο Κιότο αφιερωμένο στον Ινάρι, θεότητα του ρυζιού στον σιντοϊσμό, διάσημο για τις χιλιάδες έντονα πορτοκαλί πύλες τόριι που σχηματίζουν τούνελ στην πλαγιά του βουνού. Κάθε πύλη είναι δωρεά εταιρειών ή ιδιωτών που ελπίζουν σε καλή τύχη στις δουλειές τους.","fact":"Η διαδρομή μέσα από όλες τις πύλες και τα ιερά του βουνού παίρνει αρκετές ώρες ανηφόρας και κατηφόρας με τα πόδια.","wiki_en":"Fushimi Inari-taisha"},{"name":"Απαγορευμένη Πόλη","emoji":"🐉","meta":["Κίνα","αυτοκρατορικό ανακτορικό συγκρότημα","15ος αιώνας"],"description":"Πελώριο ανακτορικό συγκρότημα στο κέντρο του Πεκίνου, που για αιώνες ήταν η κατοικία των Κινέζων αυτοκρατόρων και παρέμενε κλειστό για τους απλούς ανθρώπους. Σήμερα στον χώρο του λειτουργεί μουσείο με πλουσιότατη συλλογή αυτοκρατορικών θησαυρών.","fact":"Ο θρύλος λέει ότι η Απαγορευμένη Πόλη έχει 9.999 δωμάτια — ένα λιγότερο από τα δέκα χιλιάδες που απέδιδαν στο παλάτι του ουράνιου κυρίαρχου.","wiki_en":"Forbidden City"},{"name":"Στρατός από Τερακότα","emoji":"🏺","meta":["Κίνα","ταφικό συγκρότημα","3ος αιώνας π.Χ."],"description":"Χιλιάδες πήλινοι πολεμιστές, άλογα και άρματα σε φυσικό μέγεθος, θαμμένα δίπλα στον τάφο του πρώτου αυτοκράτορα της Κίνας, του Τσιν Σι Χουάνγκ, για να τον προστατεύουν στη μετά θάνατον ζωή. Κάθε μορφή έχει τα δικά της χαρακτηριστικά προσώπου.","fact":"Τον στρατό τον ανακάλυψαν τυχαία το 1974 ντόπιοι αγρότες που έσκαβαν πηγάδι — έτσι βγήκε στο φως μια από τις μεγαλύτερες αρχαιολογικές ανακαλύψεις του 20ού αιώνα.","wiki_en":"Terracotta Army"},{"name":"Παλάτι Ποτάλα","emoji":"☸️","meta":["Κίνα","παλάτι-μοναστήρι","17ος αιώνας"],"description":"Επιβλητικό παλάτι σε βραχώδη λόφο της Λάσα, άλλοτε χειμερινή κατοικία των Δαλάι Λάμα και κέντρο του τιβετανικού βουδισμού. Τα λευκά και κόκκινα κτίριά του, με χιλιάδες δωμάτια, φυλάσσουν αγάλματα, κειμήλια και τους τάφους παλιών ηγεμόνων του Τιβέτ.","fact":"Το παλάτι είναι χτισμένο σε ύψος πάνω από τρεισήμισι χιλιάδες μέτρα, κάτι που το κάνει ένα από τα πιο ορεινά μνημειακά κτίσματα στον κόσμο.","wiki_en":"Potala Palace"},{"name":"Κόλπος Χα Λονγκ","emoji":"🌊","meta":["Βιετνάμ","κόλπος με καρστικά νησιά","φυσικός σχηματισμός"],"description":"Κόλπος στο βόρειο Βιετνάμ, γεμάτος χιλιάδες ασβεστολιθικά νησιά και βράχους παράξενου σχήματος που υψώνονται απευθείας από το σμαραγδί νερό. Τους επισκέπτες τους μεταφέρουν ανάμεσα στα νησιά με παραδοσιακές ξύλινες βάρκες.","fact":"Το όνομα του κόλπου σημαίνει «ο τόπος όπου ο δράκος κατεβαίνει στη θάλασσα», από παλιό βιετναμέζικο θρύλο για δράκο που προστάτευε τη χώρα.","wiki_en":"Ha Long Bay"},{"name":"Μαρίνα Μπέι Σαντς","emoji":"🏊","meta":["Σιγκαπούρη","συγκρότημα ξενοδοχείου και ψυχαγωγίας","2010"],"description":"Συγκρότημα από τρεις πύργους-ξενοδοχεία στη Σιγκαπούρη, που τους στεφανώνει μια γιγαντιαία πλατφόρμα σε σχήμα βάρκας με πισίνα στη στέγη. Από εκεί απλώνεται μπροστά σου όλο το επιχειρηματικό κέντρο της πόλης-κράτους.","fact":"Η πισίνα στη στέγη του συγκροτήματος θεωρείται μία από τις μεγαλύτερες και ψηλότερες πισίνες στον κόσμο που είναι ανοιχτές στους πελάτες ξενοδοχείου.","wiki_en":"Marina Bay Sands"},{"name":"Πύργοι Πετρόνας","emoji":"🔗","meta":["Μαλαισία","δίδυμοι ουρανοξύστες","1998"],"description":"Δύο ίδιοι χαλύβδινοι πύργοι στην Κουάλα Λουμπούρ, που για πολύ καιρό παρέμεναν τα ψηλότερα κτίρια στον κόσμο, ενωμένοι στο μέσο του ύψους τους με μια διώροφη γέφυρα. Ο γεωμετρικός σχεδιασμός τους είναι εμπνευσμένος από ισλαμικά διακοσμητικά μοτίβα.","fact":"Η γέφυρα ανάμεσα στους πύργους Πετρόνας δεν είναι στερεωμένη άκαμπτα στις δύο άκρες — αυτό επιτρέπει στην κατασκευή να μετακινείται ελαφρά όταν τα κτίρια ταλαντεύονται στον άνεμο.","wiki_en":"Petronas Towers"},{"name":"Μπορομπουντούρ","emoji":"🪷","meta":["Ινδονησία","βουδιστικός ναός","9ος αιώνας"],"description":"Ο μεγαλύτερος βουδιστικός ναός στον κόσμο, στο νησί της Ιάβας, χτισμένος ως κλιμακωτή πυραμίδα με χιλιάδες ανάγλυφα και αγάλματα του Βούδα. Οι προσκυνητές ανεβαίνουν τις βεράντες του, διανύοντας συμβολικά τον δρόμο από τον γήινο κόσμο στη φώτιση.","fact":"Στις ανώτερες βεράντες του ναού στέκουν δεκάδες κωδωνόσχημες στούπες, με ένα άγαλμα του Βούδα κρυμμένο μέσα σε κάθε μία.","wiki_en":"Borobudur"},{"name":"Καταρράκτες Βικτόριας","emoji":"🌈","meta":["Ζάμπια και Ζιμπάμπουε","καταρράκτης","φυσικός σχηματισμός"],"description":"Ένας από τους μεγαλύτερους καταρράκτες στον κόσμο, στον ποταμό Ζαμβέζη, όπου ένας τοίχος νερού γκρεμίζεται σε στενό φαράγγι με εκκωφαντικό βουητό. Το ντόπιο όνομά του σημαίνει «καπνός που βροντά» — έτσι μοιάζουν οι στήλες υδάτινης σκόνης πάνω από το φαράγγι.","fact":"Οι σταγόνες των καταρρακτών Βικτόριας ανεβαίνουν σε τόσο ύψος που με καθαρό καιρό φαίνονται από αρκετές δεκάδες χιλιόμετρα μακριά.","wiki_en":"Victoria Falls"},{"name":"Κιλιμάντζαρο","emoji":"🏔️","meta":["Τανζανία","ηφαιστειογενές βουνό","φυσικός σχηματισμός"],"description":"Το ψηλότερο βουνό της Αφρικής — ένα κοιμισμένο ηφαίστειο, με χιονισμένη κορυφή που υψώνεται απευθείας πάνω από τη σαβάνα. Την ανάβαση μπορούν να κάνουν και ανεκπαίδευτοι επισκέπτες, καθώς η διαδρομή δεν απαιτεί τεχνικό ορειβατικό εξοπλισμό.","fact":"Οι παγετώνες στην κορυφή του Κιλιμάντζαρο λιώνουν σταδιακά, και οι επιστήμονες φοβούνται ότι στο ορατό μέλλον το χιονισμένο καπέλο του βουνού μπορεί να εξαφανιστεί.","wiki_en":"Mount Kilimanjaro"},{"name":"Σερενγκέτι","emoji":"🦓","meta":["Τανζανία","εθνικό πάρκο και σαβάνα","φυσικός σχηματισμός"],"description":"Απέραντη σαβάνα στην Ανατολική Αφρική, όπου κάθε χρόνο γίνεται μια από τις μεγαλύτερες μεταναστεύσεις ζώων στον πλανήτη: εκατομμύρια γκνου και ζέβρες κινούνται ακολουθώντας τις εποχικές βροχές. Εδώ ζουν και οι μεγαλύτεροι πληθυσμοί λιονταριών και άλλων αρπακτικών της ηπείρου.","fact":"Το όνομα «Σερενγκέτι» προέρχεται από τη γλώσσα των Μασάι και σημαίνει περίπου «απέραντη πεδιάδα».","wiki_en":"Serengeti"},{"name":"Επιτραπέζιο Όρος","emoji":"🌫️","meta":["Νότια Αφρική","βουνό με επίπεδη κορυφή","φυσικός σχηματισμός"],"description":"Βουνό με σχεδόν απόλυτα επίπεδη κορυφή, που υψώνεται πάνω από το Κέιπ Τάουν και φαίνεται σχεδόν από κάθε σημείο της πόλης. Όταν τα σύννεφα στρώνονται πάνω στην επίπεδη κορυφή του, οι ντόπιοι λένε ότι το βουνό «έβαλε τραπεζομάντιλο».","fact":"Στην κορυφή του Επιτραπέζιου Όρους ανεβαίνει κανείς με τα πόδια από διάφορες διαδρομές ή σε λίγα λεπτά με τελεφερίκ με περιστρεφόμενη καμπίνα.","wiki_en":"Table Mountain"},{"name":"Έβερεστ","emoji":"🧗","meta":["Νεπάλ και Κίνα","βουνό","φυσικός σχηματισμός"],"description":"Το ψηλότερο βουνό της Γης, στα Ιμαλάια, στα σύνορα του Νεπάλ και του Τιβέτ. Η ανάβαση στην κορυφή του παραμένει εδώ και δεκαετίες μία από τις πιο τιμητικές και πιο επικίνδυνες δοκιμασίες για ορειβάτες από όλο τον κόσμο.","fact":"Την πρώτη επιβεβαιωμένη ανάβαση στο Έβερεστ πραγματοποίησαν ο Έντμουντ Χίλαρι και ο Τένζινγκ Νοργκέι το 1953.","wiki_en":"Mount Everest"},{"name":"Γιοσέμιτι","emoji":"🏔️","meta":["ΗΠΑ","εθνικό πάρκο","από το 1890"],"description":"Τα γρανιτένια τοιχώματα του Ελ Καπιτάν και του Χαφ Ντόουμ δεσπόζουν πάνω από μια κοιλάδα της Καλιφόρνια, και ένας από τους ψηλότερους καταρράκτες της Βόρειας Αμερικής βροντά εδώ από την άνοιξη μέχρι το καλοκαίρι. Σεκόγιες, αλπικά λιβάδια και παγετώδεις λίμνες κάνουν το Γιοσέμιτι σύμβολο της άγριας φύσης των ΗΠΑ.","fact":"Ο βράχος Ελ Καπιτάν στο Γιοσέμιτι είναι ένας από τους μεγαλύτερους συμπαγείς γρανιτένιους όγκους στον κόσμο και όνειρο για τους αναρριχητές όλου του πλανήτη.","wiki_en":"Yosemite National Park"},{"name":"Ζάιον","emoji":"🏞️","meta":["ΗΠΑ","εθνικό πάρκο","από το 1919"],"description":"Στενά κόκκινα φαράγγια του ποταμού Βέρτζιν χαράζουν τους αμμολιθικούς βράχους της Γιούτα, και το μονοπάτι Angels Landing, με αλυσίδες κατά μήκος του γκρεμού, έγινε μια από τις πιο γνωστές διαδρομές της χώρας. Το όνομα το έδωσαν στο πάρκο Μορμόνοι έποικοι, που είδαν στους βράχους αυτούς βιβλικό ιερό.","fact":"Το στενό φαράγγι του Ζάιον σε κάποια σημεία στενεύει σε λίγα μέτρα πλάτος, με τοιχώματα ύψους εκατοντάδων μέτρων.","wiki_en":"Zion National Park"},{"name":"Μπράις Κάνιον","emoji":"🗿","meta":["ΗΠΑ","εθνικό πάρκο","από το 1928"],"description":"Χιλιάδες πορτοκαλοκόκκινες βραχώδεις κολόνες, τα χούντου, στέκονται εδώ σχηματίζοντας ένα αμφιθέατρο που φωτίζεται πιο εντυπωσιακά την ώρα της ανατολής. Τα σχήματα των βράχων προέκυψαν από τον αιωνόβιο κύκλο παγώματος και λιώσιμου του νερού στις ρωγμές του ασβεστόλιθου.","fact":"Στο Μπράις Κάνιον βρίσκεται η μεγαλύτερη συγκέντρωση βραχωδών σχηματισμών χούντου στον κόσμο.","wiki_en":"Bryce Canyon National Park"},{"name":"Εθνικό Πάρκο Άρτσες","emoji":"🌉","meta":["ΗΠΑ","εθνικό πάρκο","από το 1971"],"description":"Σε μια σχετικά μικρή έκταση μετρώνται εδώ πάνω από δύο χιλιάδες φυσικές πέτρινες αψίδες, ανάμεσά τους και η διάσημη Ντέλικετ Αρτς. Οι κόκκινοι σχηματισμοί από αμμόλιθο δημιουργήθηκαν σε εκατομμύρια χρόνια από το νερό, τον άνεμο και τις διακυμάνσεις της θερμοκρασίας.","fact":"Η αψίδα Ντέλικετ Αρτς, που εικονίζεται στις πινακίδες κυκλοφορίας της Γιούτα, είναι μία από τις πιο αναγνωρίσιμες φυσικές αψίδες στον κόσμο.","wiki_en":"Arches National Park"},{"name":"Κοιλάδα του Θανάτου","emoji":"🌡️","meta":["ΗΠΑ","εθνικό πάρκο","από το 1994"],"description":"Ένα από τα πιο ζεστά και ξηρά μέρη του πλανήτη, όπου το καλοκαίρι το θερμόμετρο ξεπερνά τακτικά τους 50 βαθμούς. Παρά το σκληρό κλίμα, την άνοιξη, μετά τις σπάνιες βροχές, η έρημος καλύπτεται για λίγο από ένα χαλί ανθισμένων φυτών.","fact":"Στην Κοιλάδα του Θανάτου καταγράφηκε το 1913 μια από τις υψηλότερες θερμοκρασίες αέρα που έχουν μετρηθεί επίσημα στη Γη.","wiki_en":"Death Valley National Park"},{"name":"Εθνικό Πάρκο Σεκόγια","emoji":"🌲","meta":["ΗΠΑ","εθνικό πάρκο","από το 1890"],"description":"Εδώ φυτρώνουν οι γιγάντιες σεκόγιες, από τους μεγαλύτερους ζωντανούς οργανισμούς του πλανήτη, ανάμεσά τους και το δέντρο που λέγεται Στρατηγός Σέρμαν. Η ηλικία ορισμένων δέντρων του πάρκου ξεπερνά τα δύο χιλιάδες χρόνια.","fact":"Ο Στρατηγός Σέρμαν στο πάρκο Σεκόγια θεωρείται το μεγαλύτερο ζωντανό δέντρο της Γης ως προς τον όγκο του ξύλου του.","wiki_en":"Sequoia National Park"},{"name":"Εθνικό Πάρκο Γκλέισιερ","emoji":"🧊","meta":["ΗΠΑ","εθνικό πάρκο","από το 1910"],"description":"Ορεινό πάρκο στα σύνορα με τον Καναδά, που πήρε το όνομά του από τους παγετώνες που κάλυπταν κάποτε σχεδόν όλη την έκτασή του. Ο πανοραμικός δρόμος «Προς τον Ήλιο» διασχίζει το πάρκο μέσα από ένα πέρασμα και θεωρείται από τους πιο γραφικούς των ΗΠΑ.","fact":"Από τις αρκετές δεκάδες παγετώνες που έδωσαν το όνομα στο πάρκο, σήμερα έχει σωθεί μόνο ένα μικρό μέρος.","wiki_en":"Glacier National Park (U.S.)"},{"name":"Έβεργκλέιντς","emoji":"🐊","meta":["ΗΠΑ","εθνικό πάρκο","από το 1947"],"description":"Το μεγαλύτερο υποτροπικό σύστημα ελών των ΗΠΑ — ένα «ποτάμι από χόρτο» που κυλά αργά, όπου οι αλιγάτορες συνυπάρχουν με σπάνια πουλιά και συστάδες μαγγρόβιων. Είναι το μόνο μέρος στον κόσμο όπου ζουν ταυτόχρονα αλιγάτορες και κροκόδειλοι.","fact":"Στο Έβεργκλέιντς ζει ο πάνθηρας της Φλόριντα, ένα από τα σπανιότερα αρπακτικά της Βόρειας Αμερικής, με μόνο κάποιες εκατοντάδες άτομα στη φύση.","wiki_en":"Everglades National Park"},{"name":"Τζόσουα Τρι","emoji":"🌵","meta":["ΗΠΑ","εθνικό πάρκο","από το 1994"],"description":"Το ερημικό αυτό πάρκο στην Καλιφόρνια πήρε το όνομά του από τη γιούκα, της οποίας οι παράξενες σιλουέτες θύμισαν στους Μορμόνους έποικους τον βιβλικό προφήτη με υψωμένα χέρια. Εδώ συναντιούνται δύο έρημοι — της Μοχάβε και του Κολοράντο — με τα δικά τους οικοσυστήματα.","fact":"Τα δέντρα Τζόσουα, που έδωσαν το όνομα στο πάρκο, δεν είναι στην πραγματικότητα δέντρα, αλλά γιγάντια μέλη της οικογένειας των σπαραγγιών.","wiki_en":"Joshua Tree National Park"},{"name":"Λίμνη Κρέιτερ","emoji":"🌋","meta":["ΗΠΑ","εθνικό πάρκο","από το 1902"],"description":"Η βαθύτερη λίμνη των ΗΠΑ γεμίζει την καλδέρα του ηφαιστείου Μαζάμα, που κατέρρευσε πριν από χιλιάδες χρόνια. Το νερό της είναι τόσο καθαρό που φαίνεται βαθιά μπλε, και ανανεώνεται μόνο από τη βροχή και το χιόνι.","fact":"Στη λίμνη Κρέιτερ επιπλέει πάνω από έναν αιώνα ένας κορμός δέντρου σε κατακόρυφη θέση, που τον ονόμασαν «Γέρο της λίμνης».","wiki_en":"Crater Lake National Park"},{"name":"Όρος Ρενίρ","emoji":"🗻","meta":["ΗΠΑ","ενεργό ηφαίστειο","εθνικό πάρκο από το 1899"],"description":"Χιονισμένο στρωματοηφαίστειο που δεσπόζει πάνω από το Σιάτλ και θεωρείται ένα από τα πιο επικίνδυνα ενεργά ηφαίστεια των ΗΠΑ, λόγω της γειτνίασης με μεγάλες πόλεις. Οι παγετώνες στις πλαγιές του τροφοδοτούν αρκετά ποτάμια της περιοχής.","fact":"Το όρος Ρενίρ είναι η ψηλότερη κορυφή του ηφαιστειακού τόξου των Κασκάντ και μία από τις πιο παγωμένες κορυφές των ΗΠΑ εκτός Αλάσκας.","wiki_en":"Mount Rainier"},{"name":"Φαράγγι της Αντιλόπης","emoji":"🌀","meta":["ΗΠΑ","στενό σχισμοειδές φαράγγι","δημοφιλές από τη δεκαετία του 1990"],"description":"Τα φιδωτά πορτοκαλί τοιχώματα αυτού του στενού φαραγγιού στην Αριζόνα είναι γυαλισμένα από την αιωνόβια διάβρωση του αμμόλιθου και φωτίζονται από δέσμες ήλιου που μπαίνουν από ψηλά. Βρίσκεται σε γη των Ναβάχο και η επίσκεψη γίνεται μόνο με ντόπιο ξεναγό.","fact":"Το φαράγγι διαμορφώθηκε μέσα σε χιλιάδες χρόνια από ξαφνικές πλημμύρες, που ακόμη σήμερα αποτελούν κίνδυνο για τους επισκέπτες.","wiki_en":"Antelope Canyon"},{"name":"Πέταλο του Κολοράντο","emoji":"🌊","meta":["ΗΠΑ","καμπή στο φαράγγι του Κολοράντο","δημοφιλές από τη δεκαετία του 2010"],"description":"Εδώ ο ποταμός Κολοράντο κάνει μια σχεδόν κλειστή θηλιά γύρω από ένα βραχώδες ακρωτήρι, σχηματίζοντας μια εικόνα που θυμίζει πέταλο. Από την εξέδρα θέασης πάνω από τον γκρεμό ανοίγεται ένα από τα πιο φωτογραφημένα τοπία της αμερικανικής Νοτιοδύσης.","fact":"Η καμπή του ποταμού σε σχήμα πετάλου σχηματίστηκε σε εκατομμύρια χρόνια, όσο το Κολοράντο έκοβε τα στρώματα αμμόλιθου του υψιπέδου.","wiki_en":"Horseshoe Bend (Arizona)"},{"name":"Πύργος Ουίλις","emoji":"🏙️","meta":["ΗΠΑ","ουρανοξύστης","χτίστηκε το 1973"],"description":"Για δεκαετίες ήταν το ψηλότερο κτίριο στον κόσμο, μέχρι που τον ξεπέρασαν οι ουρανοξύστες της Ασίας. Στους πάνω ορόφους υπάρχει εξέδρα θέασης με γυάλινα κουτιά που προεξέχουν έξω από την πρόσοψη του κτιρίου.","fact":"Τα γυάλινα κουτιά Skydeck στους πάνω ορόφους του πύργου Ουίλις επιτρέπουν να κοιτάξεις κάτω μέσα από διάφανο δάπεδο.","wiki_en":"Willis Tower"},{"name":"Σπέις Νιντλ","emoji":"🛸","meta":["ΗΠΑ","πύργος με εξέδρα θέασης","χτίστηκε το 1962"],"description":"Πύργος με δισκοειδή κορυφή, που χτίστηκε στο Σιάτλ για την Παγκόσμια Έκθεση και από τότε έγινε σύμβολο της πόλης. Σε ύψος αρκετών δεκάδων ορόφων βρίσκονται μια εξέδρα θέασης και ένα περιστρεφόμενο εστιατόριο.","fact":"Μετά την ανακαίνιση, στην εξέδρα θέασης του Σπέις Νιντλ προστέθηκε περιστρεφόμενο γυάλινο δάπεδο, μέσα από το οποίο φαίνεται η πόλη από κάτω.","wiki_en":"Space Needle"},{"name":"Μνημείο Λίνκολν","emoji":"🏛️","meta":["ΗΠΑ","μνημείο","άνοιξε το 1922"],"description":"Μνημειακό κτίριο σε νεοκλασικό ύφος στην Εθνική Λεωφόρο της Ουάσιγκτον, που φυλάσσει ένα γιγαντιαίο μαρμάρινο άγαλμα του δέκατου έκτου προέδρου των ΗΠΑ. Πάνω στα σκαλιά του εκφώνησε το 1963 τον διάσημο λόγο του ο Μάρτιν Λούθερ Κινγκ.","fact":"Η καθιστή μορφή του Λίνκολν μέσα στο μνημείο φτάνει περίπου τα έξι μέτρα και είναι συναρμολογημένη από πολλούς μαρμάρινους όγκους.","wiki_en":"Lincoln Memorial"},{"name":"Μνημείο Ουάσιγκτον","emoji":"🗼","meta":["ΗΠΑ","οβελίσκος","ολοκληρώθηκε το 1884"],"description":"Μαρμάρινος οβελίσκος στην Εθνική Λεωφόρο της Ουάσιγκτον, που υψώθηκε στη μνήμη του πρώτου προέδρου των ΗΠΑ. Μετά την ολοκλήρωσή του παρέμεινε για λίγα χρόνια το ψηλότερο κατασκεύασμα στον κόσμο, ώσπου τον ξεπέρασε ο Πύργος του Άιφελ. Η ανέγερση κράτησε δεκαετίες και διακόπηκε από έλλειψη χρημάτων.","fact":"Λόγω της μεγάλης διακοπής στην ανέγερση, το κάτω και το πάνω μέρος του οβελίσκου είναι από μάρμαρο με ελαφρώς διαφορετικές αποχρώσεις.","wiki_en":"Washington Monument"},{"name":"Καπιτώλιο των ΗΠΑ","emoji":"🏛️","meta":["ΗΠΑ","κτίριο του κοινοβουλίου","η ανέγερση ξεκίνησε το 1793"],"description":"Η έδρα του Κογκρέσου των ΗΠΑ, με τον αναγνωρίσιμο λευκό θόλο, στέκει στον λόφο που εξαιτίας της ονομάστηκε Καπιτώλιο. Ο πρώτος λίθος τοποθετήθηκε στα τέλη του 18ου αιώνα, ενώ ο σημερινός θόλος ολοκληρώθηκε στα χρόνια του Εμφυλίου Πολέμου.","fact":"Η κατασκευή του θόλου του Καπιτωλίου συνεχίστηκε ακόμη και στα χρόνια του Εμφυλίου Πολέμου, ως σύμβολο της ενότητας της χώρας.","wiki_en":"United States Capitol"},{"name":"Φράγμα Χούβερ","emoji":"🌊","meta":["ΗΠΑ","φράγμα","χτίστηκε στη δεκαετία του 1930"],"description":"Ένα από τα μεγαλύτερα φράγματα από σκυρόδεμα της εποχής του έφραξε τον ποταμό Κολοράντο στα σύνορα της Νεβάδα και της Αριζόνα, δημιουργώντας τη λίμνη Μιντ. Η κατασκευή έγινε σύμβολο των μηχανικών δυνατοτήτων των ΗΠΑ στην καρδιά της Μεγάλης Ύφεσης.","fact":"Όταν χτίστηκε, το φράγμα Χούβερ ήταν το ψηλότερο φράγμα στον κόσμο, και οι τουρμπίνες του τροφοδοτούν ακόμη σήμερα με ρεύμα αρκετές πολιτείες.","wiki_en":"Hoover Dam"},{"name":"Ινστιτούτο Σμιθσόνιαν","emoji":"🏛️","meta":["ΗΠΑ","μουσειακό και ερευνητικό συγκρότημα","ιδρύθηκε το 1846"],"description":"Το μεγαλύτερο μουσειακό και ερευνητικό συγκρότημα στον κόσμο συγκεντρώνει δεκάδες μουσεία και έναν ζωολογικό κήπο στην Ουάσιγκτον, με ελεύθερη είσοδο στα περισσότερα. Ιδρύθηκε με χρήματα Βρετανού επιστήμονα που δεν πάτησε ποτέ το πόδι του στις ΗΠΑ.","fact":"Στις συλλογές του ινστιτούτου φυλάσσονται δεκάδες εκατομμύρια εκθέματα — από το αεροπλάνο των αδελφών Ράιτ μέχρι το διάσημο διαμάντι «Χόουπ».","wiki_en":"Smithsonian Institution"},{"name":"Αγορά Πάικ Πλέις","emoji":"🐟","meta":["ΗΠΑ","αγορά","άνοιξε το 1907"],"description":"Μία από τις παλαιότερες αγορές παραγωγών των ΗΠΑ που λειτουργούν αδιάκοπα, στο Σιάτλ, διάσημη για τους ψαράδες που πετούν σολομούς πάνω από τον πάγκο για να διασκεδάσουν το κοινό. Εδώ δίπλα άνοιξε και η πρώτη καφετέρια της αλυσίδας Starbucks.","fact":"Η αγορά εμφανίστηκε το 1907, όταν οι κάτοικοι της πόλης απαίτησαν να αγοράζουν προϊόντα απευθείας από τους αγρότες, χωρίς μεσάζοντες.","wiki_en":"Pike Place Market"},{"name":"Ντίσνεϊ Γουόρλντ","emoji":"🏰","meta":["ΗΠΑ","πάρκο ψυχαγωγίας","άνοιξε το 1971"],"description":"Το μεγαλύτερο σε έκταση πάρκο ψυχαγωγίας στον κόσμο απλώνεται στη Φλόριντα και περιλαμβάνει αρκετές θεματικές ζώνες, ξενοδοχεία και γήπεδα γκολφ. Το κάστρο της Σταχτοπούτας στο κέντρο του έγινε μια από τις πιο αναγνωρίσιμες σιλουέτες της βιομηχανίας ψυχαγωγίας.","fact":"Η έκταση του Ντίσνεϊ Γουόρλντ στη Φλόριντα είναι συγκρίσιμη με μια μικρή πόλη και ξεπερνά το μέγεθος του Μανχάταν.","wiki_en":"Walt Disney World"},{"name":"Κρατήρας Μετέωρ","emoji":"☄️","meta":["ΗΠΑ","κρατήρας μετεωρίτη","πριν από περίπου 50.000 χρόνια"],"description":"Ένας από τους καλύτερα διατηρημένους κρατήρες μετεωρίτη στη Γη δημιουργήθηκε στην έρημο της Αριζόνα από την πρόσκρουση ενός μικρού μεταλλικού αστεροειδούς. Εδώ έκαναν εκπαίδευση οι αστροναύτες του προγράμματος «Απόλλων» πριν από τις πτήσεις στη Σελήνη.","fact":"Για πολύ καιρό πίστευαν ότι ο λάκκος προήλθε από ηφαιστειακή δραστηριότητα, και η μετεωριτική του καταγωγή αναγνωρίστηκε μόλις τον 20ό αιώνα.","wiki_en":"Meteor Crater"},{"name":"Άλαμο","emoji":"🪖","meta":["ΗΠΑ","ιεραποστολή-φρούριο","ιδρύθηκε τον 18ο αιώνα"],"description":"Παλιά καθολική ιεραποστολή στο Σαν Αντόνιο του Τέξας, που έγινε τόπος μιας διάσημης πολιορκίας στον πόλεμο της ανεξαρτησίας του Τέξας από το Μεξικό. Η φράση «Θυμήσου το Άλαμο!» παραμένει στην αμερικανική κουλτούρα σύμβολο αντοχής μπροστά στην ήττα.","fact":"Σχεδόν όλοι οι υπερασπιστές του Άλαμο σκοτώθηκαν στην πολιορκία του 1836, αλλά η αντίστασή τους έγινε σύμβολο για τον παραπέρα αγώνα των Τεξανών.","wiki_en":"Alamo Mission in San Antonio"},{"name":"Ντενάλι","emoji":"🏔️","meta":["ΗΠΑ","το ψηλότερο βουνό της Βόρειας Αμερικής","εθνικό πάρκο από το 1917"],"description":"Η χιονισμένη αυτή κορυφή στην Αλάσκα είναι το ψηλότερο σημείο της Βόρειας Αμερικής και τραβά ορειβάτες από όλο τον κόσμο με τις σκληρές συνθήκες της ανάβασης. Το όνομα «Ντενάλι» στη γλώσσα των ιθαγενών Αθαπάσκων σημαίνει «ψηλό».","fact":"Η υψομετρική διαφορά από τη βάση έως την κορυφή στο Ντενάλι είναι από τις μεγαλύτερες στον κόσμο — μεγαλύτερη από του Έβερεστ, που στέκει σε ψηλό υψίπεδο.","wiki_en":"Denali"},{"name":"Καθεδρικός του Αγίου Ισαάκ","emoji":"⛪","meta":["Ρωσία","καθεδρικός ναός","χτίστηκε στα μέσα του 19ου αιώνα"],"description":"Ένας από τους μεγαλύτερους θολωτούς ναούς στον κόσμο χτιζόταν στην Πετρούπολη σχεδόν τέσσερις δεκαετίες και έγινε η αρχιτεκτονική ταυτότητα της πόλης. Από την κιονοστοιχία κάτω από τον θόλο ανοίγεται πανοραμική θέα στο ιστορικό κέντρο.","fact":"Οι μονολιθικοί γρανιτένιοι κίονες των προπύλων ζυγίζουν περίπου εκατό τόνους ο καθένας, και τοποθετήθηκαν πριν ακόμη υψωθούν οι τοίχοι του ναού.","wiki_en":"Saint Isaac's Cathedral"},{"name":"Καθεδρικός του Καζάν","emoji":"⛪","meta":["Ρωσία","καθεδρικός ναός","χτίστηκε στις αρχές του 19ου αιώνα"],"description":"Ο ναός στη λεωφόρο Νιέφσκι της Πετρούπολης χτίστηκε κατά το πρότυπο της Βασιλικής του Αγίου Πέτρου στη Ρώμη και στεφανώνεται από ημικυκλική κιονοστοιχία. Μετά τον πόλεμο του 1812 κατά του Ναπολέοντα θάφτηκε εδώ ο στρατάρχης Μιχαήλ Κουτούζοφ.","fact":"Ο ναός πήρε το όνομά του από την εικόνα της Θεοτόκου του Καζάν, της οποίας το σεβάσμιο αντίγραφο φυλασσόταν εδώ ως το κύριο ιερό κειμήλιο.","wiki_en":"Kazan Cathedral, Saint Petersburg"},{"name":"Ναός του Σωτήρος Χριστού","emoji":"⛪","meta":["Ρωσία","καθεδρικός ναός","ανακατασκευάστηκε στη δεκαετία του 1990"],"description":"Ο μεγαλύτερος ορθόδοξος ναός της Ρωσίας, στη Μόσχα, ανατινάχτηκε στα σοβιετικά χρόνια και ξαναχτίστηκε από την αρχή στα τέλη του 20ού αιώνα, κατά το πρότυπο του χαμένου αρχικού. Ο πρώτος ναός χτίστηκε στη μνήμη της νίκης στον πόλεμο του 1812.","fact":"Στη θέση του γκρεμισμένου ναού λειτουργούσε για αρκετές δεκαετίες η υπαίθρια πισίνα «Μόσχα», που δούλευε ακόμη και τον χειμώνα.","wiki_en":"Cathedral of Christ the Saviour"},{"name":"Μονή Νοβοντέβιτσι","emoji":"⛪","meta":["Ρωσία","μοναστήρι","ιδρύθηκε τον 16ο αιώνα"],"description":"Ένα από τα πιο γνωστά γυναικεία μοναστήρια της Μόσχας ιδρύθηκε για την επιστροφή του Σμολένσκ στα ρωσικά εδάφη. Στον χώρο του μοναστηριού βρίσκεται νεκροταφείο όπου είναι θαμμένες πολλές σημαντικές προσωπικότητες του ρωσικού πολιτισμού και της ιστορίας.","fact":"Το αρχιτεκτονικό σύνολο της μονής Νοβοντέβιτσι είναι εγγεγραμμένο στον κατάλογο Παγκόσμιας Κληρονομιάς της UNESCO.","wiki_en":"Novodevichy Convent"},{"name":"Πινακοθήκη Τρετιακόφ","emoji":"🖼️","meta":["Ρωσία","μουσείο τέχνης","ιδρύθηκε το 1856"],"description":"Η μεγαλύτερη συλλογή ρωσικών εικαστικών τεχνών ξεπήδησε από την ιδιωτική συλλογή του Μοσχοβίτη εμπόρου και μαικήνα Πάβελ Τρετιακόφ. Σήμερα η πινακοθήκη φυλάσσει έργα από παλιές ρωσικές εικόνες έως τους πίνακες των Περιπλανώμενων και της πρωτοπορίας.","fact":"Η συλλογή της πινακοθήκης ξεκίνησε από την προσωπική συλλογή πινάκων του εμπόρου Πάβελ Τρετιακόφ, που τη δώρισε στην πόλη της Μόσχας.","wiki_en":"Tretyakov Gallery"},{"name":"Ρωσικό Μουσείο","emoji":"🎨","meta":["Ρωσία","μουσείο τέχνης","ιδρύθηκε το 1895"],"description":"Το πρώτο κρατικό μουσείο ρωσικών εικαστικών τεχνών της χώρας βρίσκεται στην Πετρούπολη, στο Ανάκτορο Μιχαΐλοφσκι. Η συλλογή του καλύπτει σχεδόν όλη την ιστορία της ρωσικής ζωγραφικής και γλυπτικής, από τις εικόνες έως την πρωτοπορία του 20ού αιώνα.","fact":"Το Ρωσικό Μουσείο ιδρύθηκε με διάταγμα του αυτοκράτορα Νικολάου Β΄ και έγινε το πρώτο κρατικό μουσείο εθνικής τέχνης στη Ρωσία.","wiki_en":"Russian Museum"},{"name":"VDNKh","emoji":"🎡","meta":["Ρωσία","εκθεσιακό συγκρότημα","άνοιξε το 1939"],"description":"Το γιγαντιαίο εκθεσιακό συγκρότημα στη Μόσχα δημιουργήθηκε αρχικά για να δείχνει τα επιτεύγματα της σοβιετικής γεωργίας και βιομηχανίας. Σήμερα τα περίπτερά του σε σταλινικό αυτοκρατορικό ύφος συνυπάρχουν με συντριβάνια, μουσεία και χώρους πάρκου.","fact":"Το συντριβάνι «Φιλία των Λαών» στο VDNKh είναι στολισμένο με επιχρυσωμένα γλυπτά που συμβολίζουν τις σοβιετικές δημοκρατίες της ΕΣΣΔ.","wiki_en":"VDNKh","wiki_ru":"Выставка достижений народного хозяйства"},{"name":"Πύργος Οστάνκινο","emoji":"📡","meta":["Ρωσία","τηλεοπτικός πύργος","χτίστηκε το 1967"],"description":"Ένας από τους ψηλότερους τηλεοπτικούς πύργους στον κόσμο δεσπόζει πάνω από τη Μόσχα και για δεκαετίες εξασφάλιζε την τηλεοπτική κάλυψη όλης της περιοχής. Σε ύψος αρκετών εκατοντάδων μέτρων λειτουργεί εξέδρα θέασης με θέα στην πόλη.","fact":"Για λίγα χρόνια μετά την κατασκευή του, ο πύργος Οστάνκινο ήταν το ψηλότερο ελεύθερο κατασκεύασμα στον κόσμο.","wiki_en":"Ostankino Tower"},{"name":"Κανόνι του Τσάρου","emoji":"⚔️","meta":["Ρωσία","κανόνι-μνημείο","χυτεύτηκε το 1586"],"description":"Το γιγαντιαίο χάλκινο κανόνι είναι τοποθετημένο στον χώρο του Κρεμλίνου της Μόσχας και θεωρείται ένα από τα μεγαλύτερα σε διαμέτρημα πυροβόλα της ιστορίας. Οι ιστορικοί διαφωνούν αν το κανόνι πυροβόλησε ποτέ, έστω και μία φορά.","fact":"Παρά τις εντυπωσιακές του διαστάσεις, δεν υπάρχουν αξιόπιστες μαρτυρίες ότι το Κανόνι του Τσάρου χρησιμοποιήθηκε ποτέ σε μάχη.","wiki_en":"Tsar Cannon"},{"name":"Καμπάνα του Τσάρου","emoji":"🔔","meta":["Ρωσία","καμπάνα-μνημείο","χυτεύτηκε το 1735"],"description":"Η μεγαλύτερη καμπάνα στον κόσμο δεν ανέβηκε ποτέ σε κωδωνοστάσιο: σε μια πυρκαγιά αποκολλήθηκε από αυτήν ένα τεράστιο κομμάτι. Σήμερα στέκει σε βάθρο μέσα στο Κρεμλίνο της Μόσχας, ως μνημείο της χυτευτικής τέχνης του 18ου αιώνα.","fact":"Από την Καμπάνα του Τσάρου έσπασε ένα κομμάτι αρκετών τόνων προτού καταφέρουν να την ανεβάσουν και να τη χρησιμοποιήσουν.","wiki_en":"Tsar Bell"},{"name":"Λόφος Μαμάγιεφ","emoji":"🕊️","meta":["Ρωσία","μνημειακό συγκρότημα","άνοιξε το 1967"],"description":"Ο λόφος στο Βόλγκογκραντ, όπου στη μάχη του Στάλινγκραντ έγιναν μερικές από τις σκληρότερες συγκρούσεις του Β΄ Παγκοσμίου Πολέμου, έγινε τόπος ενός από τα μεγαλύτερα πολεμικά μνημεία στον κόσμο. Τον στεφανώνει το άγαλμα «Η Μητέρα Πατρίδα Καλεί».","fact":"Όταν αποκαλύφθηκε, το άγαλμα «Η Μητέρα Πατρίδα Καλεί» ήταν το ψηλότερο γλυπτό στον κόσμο.","wiki_en":"Mamayev Kurgan"},{"name":"Κουρονική Λωρίδα","emoji":"🏖️","meta":["Ρωσία","αμμώδης λωρίδα","εθνικό πάρκο από το 1987"],"description":"Στενή λωρίδα άμμου ανάμεσα στη Βαλτική Θάλασσα και τη λιμνοθάλασσα της Κουρονίας απλώνεται για σχεδόν εκατό χιλιόμετρα και μοιράζεται ανάμεσα στη Ρωσία και τη Λιθουανία. Εδώ συναντάς γιγάντιους αμμόλοφους και το «χορεύον δάσος», με παράξενα λυγισμένους κορμούς πεύκων.","fact":"Στο «χορεύον δάσος» της Κουρονικής Λωρίδας οι κορμοί των πεύκων είναι στριμμένοι και λυγισμένοι για λόγους που δεν έχουν εξηγηθεί πλήρως.","wiki_en":"Curonian Spit"},{"name":"Κοιλάδα των Θερμοπιδάκων","emoji":"♨️","meta":["Ρωσία","πεδίο θερμοπιδάκων","ανακαλύφθηκε το 1941"],"description":"Μία από τις λίγες μεγάλες συγκεντρώσεις θερμοπιδάκων στον κόσμο βρίσκεται στην Καμτσάτκα, σε ένα δυσπρόσιτο φαράγγι του ποταμού Γκέιζερναγια. Δεκάδες θερμές πηγές και πίδακες ατμού κάνουν το μέρος ένα σπάνιο γεωθερμικό φαινόμενο.","fact":"Την Κοιλάδα των Θερμοπιδάκων στην Καμτσάτκα ανακάλυψε το 1941 η ερευνήτρια Τατιάνα Ουστίνοβα, που έπεσε πάνω της τυχαία σε μια αποστολή.","wiki_en":"Valley of Geysers"},{"name":"Στύλοι του Λένα","emoji":"🪨","meta":["Ρωσία","βραχώδεις στύλοι","εθνικό πάρκο από το 1995"],"description":"Κατακόρυφοι ασβεστολιθικοί βράχοι ύψους δεκάδων μέτρων απλώνονται για πολλά χιλιόμετρα κατά μήκος του ποταμού Λένα στη Γιακουτία. Στις αποθέσεις της περιοχής βρίσκουν οστά μαμούθ και άλλων ζώων της παγετώδους περιόδου.","fact":"Στα περίχωρα των Στύλων του Λένα βρίσκουν τακτικά καλά διατηρημένα λείψανα μαμούθ και άλλων απολιθωμένων ζώων.","wiki_en":"Lena Pillars"},{"name":"Υψίπεδο Πουτοράνα","emoji":"⛰️","meta":["Ρωσία","βασαλτικό υψίπεδο","προστατευόμενη περιοχή από το 1988"],"description":"Το δυσπρόσιτο αυτό υψίπεδο στη βόρεια Σιβηρία είναι χαραγμένο από βαθιά φαράγγια και εκατοντάδες καταρράκτες, και τα βασαλτικά σκαλοπάτια του θυμίζουν αναβαθμίδες. Λόγω της απόστασης, η περιοχή παραμένει από τις λιγότερο επισκέψιμες της Ρωσίας.","fact":"Στο υψίπεδο Πουτοράνα βρίσκεται ένας από τους ψηλότερους καταρράκτες της Ρωσίας, κρυμμένος σε δυσπρόσιτο φαράγγι.","wiki_en":"Putorana Plateau"},{"name":"Νησιά Σολοβέτσκι","emoji":"🏝️","meta":["Ρωσία","αρχιπέλαγος με μοναστήρι","μοναστήρι από τον 15ο αιώνα"],"description":"Το αρχιπέλαγος στη Λευκή Θάλασσα είναι γνωστό για ένα παλιό μοναστήρι που σε διαφορετικές εποχές ήταν και πνευματικό κέντρο και τόπος φυλάκισης. Το σκληρό κλίμα και η απόσταση διαμόρφωσαν για αιώνες μια ιδιαίτερη καθημερινότητα για τους κατοίκους του.","fact":"Στα σοβιετικά χρόνια, στον χώρο της μονής Σολοβέτσκι λειτούργησε ένα από τα πρώτα στρατόπεδα ειδικού σκοπού.","wiki_en":"Solovetsky Islands"},{"name":"Χρυσό Δαχτυλίδι της Ρωσίας","emoji":"💍","meta":["Ρωσία","τουριστική διαδρομή","διαμορφώθηκε στη δεκαετία του 1960"],"description":"Το όνομα ενώνει αρκετές αρχαίες πόλεις γύρω από τη Μόσχα — το Σούζνταλ, το Βλαντίμιρ, το Σέργκιεφ Ποσάντ και άλλες — που διατήρησαν λευκόλιθους ναούς και κρεμλίνα από την εποχή πριν από τους Μογγόλους. Η διαδρομή διαμορφώθηκε ως τουριστικό σήμα στα σοβιετικά χρόνια.","fact":"Τον όρο «Χρυσό Δαχτυλίδι» τον επινόησε στη δεκαετία του 1960 ο δημοσιογράφος Γιούρι Μπιτσκόφ, που ένωσε τις παλιές πόλεις σε μία τουριστική διαδρομή.","wiki_en":"Golden Ring of Russia","wiki_ru":"Золотое кольцо России"},{"name":"Πλατεία των Ανακτόρων","emoji":"🏛️","meta":["Ρωσία","πλατεία","διαμορφώθηκε στον 18ο–19ο αιώνα"],"description":"Η κεντρική πλατεία της Πετρούπολης περιβάλλεται από τα Χειμερινά Ανάκτορα και το κτίριο του Γενικού Επιτελείου με τη θριαμβική αψίδα, ενώ στο κέντρο υψώνεται η Στήλη του Αλεξάνδρου. Εδώ εκτυλίχθηκαν καθοριστικά γεγονότα της ρωσικής ιστορίας, ανάμεσά τους και εκείνα του 1917.","fact":"Η Στήλη του Αλεξάνδρου στο κέντρο της πλατείας στηρίζεται στο βάθρο της μόνο από το ίδιο της το βάρος, χωρίς στερεώσεις.","wiki_en":"Palace Square"},{"name":"Γέφυρα των Ανακτόρων","emoji":"🌉","meta":["Ρωσία","ανοιγόμενη γέφυρα","χτίστηκε το 1916"],"description":"Μία από τις πιο αναγνωρίσιμες ανοιγόμενες γέφυρες της Πετρούπολης ενώνει την προκυμαία των Ανακτόρων με το νησί Βασίλιεφσκι πάνω από τον Νέβα. Το άνοιγμα των φύλλων της τις νύχτες, στην περίοδο της ναυσιπλοΐας, έγινε σύμβολο της πόλης και τουριστικό τελετουργικό.","fact":"Μόνιμη γέφυρα στο σημείο αυτό εμφανίστηκε μόλις στις αρχές του 20ού αιώνα — πριν από αυτό τις όχθες του Νέβα ένωνε πλωτή γέφυρα πάνω σε φορτηγίδες.","wiki_en":"Palace Bridge"},{"name":"Βαλαάμ","emoji":"🏝️","meta":["Ρωσία","νησί με μοναστήρι","πιθανώς 14ος αιώνας"],"description":"Το αρχιπέλαγος στη λίμνη Λαντόγκα είναι γνωστό για τη σκληρή βορινή φύση του και για ένα από τα παλαιότερα μοναστήρια του ρωσικού Βορρά. Βραχώδεις ακτές, πευκοδάση και απομονωμένα ερημητήρια τραβούσαν εδώ για αιώνες προσκυνητές και ζωγράφους.","fact":"Τα τοπία του Βαλαάμ ενέπνευσαν πολλούς Ρώσους ζωγράφους, ανάμεσά τους και τον Ιβάν Σίσκιν, που βρέθηκε εδώ στα νιάτα του.","wiki_en":"Valaam"},{"name":"Παγωμένο Σπήλαιο Κουνγκούρ","emoji":"🧊","meta":["Ρωσία","καρστικό σπήλαιο","ανοιχτό σε επισκέπτες από το 1914"],"description":"Ένα από τα μεγαλύτερα καρστικά σπήλαια της Ρωσίας, στα Ουράλια, φημίζεται για τους παγωμένους θαλάμους του, τις υπόγειες λίμνες και τους παράξενους κρυστάλλους πάχνης. Μέρος των διαδρόμων του έχει τεχνητό φωτισμό, που μετατρέπει τον πάγο σε πολύχρωμα σχέδια.","fact":"Σε ορισμένους θαλάμους του σπηλαίου Κουνγκούρ ο πάγος διατηρείται όλο τον χρόνο, ακόμη και στην καρδιά του καλοκαιριού των Ουραλίων.","wiki_en":"Kungur Ice Cave"},{"name":"Στύλοι του Κρασνογιάρσκ","emoji":"⛰️","meta":["Ρωσία","βραχώδεις στύλοι","προστατευόμενη περιοχή από το 1925"],"description":"Οι παράξενοι συηνιτικοί βράχοι στην τάιγκα κοντά στο Κρασνογιάρσκ τραβούσαν από παλιά τους αναρριχητές, ανάμεσά τους και τους ντόπιους «στολμπίστες», που σκαρφαλώνουν χωρίς ασφάλεια. Η προστατευόμενη περιοχή δημιουργήθηκε για να διατηρηθεί το μοναδικό τοπίο και η τάιγκα γύρω του.","fact":"Η προστατευόμενη περιοχή των Στύλων είναι από τις παλαιότερες της Ρωσίας: οι βράχοι προστατεύονται εδώ και περίπου εκατό χρόνια.","wiki_en":"Stolby Nature Reserve"},{"name":"Ολχόν","emoji":"🏝️","meta":["Ρωσία","το μεγαλύτερο νησί της Βαϊκάλης","μέρος εθνικού πάρκου από το 1986"],"description":"Το μεγαλύτερο νησί της Βαϊκάλης θεωρείται πνευματικό κέντρο του βουριάτικου σαμανισμού και έχει μία από τις υψηλότερες αναλογίες ηλιόλουστων ημερών στη Ρωσία. Ο βράχος Σαμάνκα στην ακτή του είναι ένα από τα πιο σεβαστά φυσικά σύμβολα της περιοχής.","fact":"Ο βράχος Σαμάνκα στο Ολχόν θεωρείται ένας από τους εννέα ιερούς τόπους της Ασίας στις παραδόσεις του τοπικού σαμανισμού.","wiki_en":"Olkhon"},{"name":"Ντομπάι","emoji":"🎿","meta":["Ρωσία","χιονοδρομικό κέντρο","τουριστικό κέντρο από τη δεκαετία του 1920"],"description":"Το ορεινό αυτό χωριό στον Καύκασο, περιτριγυρισμένο από παγετώνες και κορυφές πάνω από τέσσερις χιλιάδες μέτρα, έγινε ένα από τα πρώτα σοβιετικά κέντρα ορειβασίας και χιονοδρομίας. Τα τελεφερίκ ανεβάζουν τους επισκέπτες σε εξέδρες με θέα στο Έλμπρους και στην κύρια οροσειρά του Καυκάσου.","fact":"Από τα σημεία θέασης πάνω από το Ντομπάι, με καθαρό καιρό, διακρίνεται το Έλμπρους — η ψηλότερη κορυφή της Ευρώπης.","wiki_en":"Dombai","wiki_ru":"Домбай"},{"name":"Κρεμλίνο του Σούζνταλ","emoji":"🏰","meta":["Ρωσία","κρεμλίνο","ιδρύθηκε τον 11ο αιώνα"],"description":"Το αρχαιότερο μέρος της πόλης Σούζνταλ διατήρησε τα χωμάτινα αναχώματά του και έναν ναό με χρυσές πύλες, σπάνιες για την αρχιτεκτονική πριν από τους Μογγόλους. Το μικρό μέγεθος και η απουσία μεγάλης σύγχρονης δόμησης κάνουν το Σούζνταλ ένα ιδιότυπο υπαίθριο μουσείο.","fact":"Το Κρεμλίνο του Σούζνταλ είναι ένα από τα λίγα στη Ρωσία όπου σχεδόν δεν υπάρχουν μεταγενέστερα κτίσματα που κρύβουν την αρχαία όψη της πόλης.","wiki_en":"Suzdal Kremlin"},{"name":"Πύργος του Λονδίνου","emoji":"🏰","meta":["Ηνωμένο Βασίλειο","φρούριο-μουσείο","χτίστηκε τον 11ο αιώνα"],"description":"Το φρούριο στον Τάμεση θεμελίωσε ο Γουλιέλμος ο Κατακτητής και στην ιστορία του υπήρξε βασιλική κατοικία, φυλακή και θησαυροφυλάκιο των βασιλικών κοσμημάτων. Τα μαύρα κοράκια που ζουν στον χώρο του Πύργου, κατά τον θρύλο, φυλάνε τη βρετανική μοναρχία.","fact":"Ο θρύλος λέει ότι αν τα κοράκια εγκαταλείψουν κάποτε τον Πύργο, η βρετανική μοναρχία θα πέσει — γι' αυτό και τους κόβουν τα φτερά.","wiki_en":"Tower of London"},{"name":"Αββαείο του Ουέστμινστερ","emoji":"⛪","meta":["Ηνωμένο Βασίλειο","αββαείο","γοτθική μορφή από τον 13ο αιώνα"],"description":"Το γοτθικό αυτό αββαείο στο Λονδίνο είναι εδώ και αιώνες ο τόπος στέψης και ταφής των Βρετανών μοναρχών, αλλά και πολλών σπουδαίων προσώπων της επιστήμης και της τέχνης. Εδώ παντρεύτηκαν το 2011 ο πρίγκιπας Γουίλιαμ και η Κέιτ Μίντλετον.","fact":"Στο Αββαείο του Ουέστμινστερ είναι θαμμένοι ο Ισαάκ Νεύτων, ο Κάρολος Δαρβίνος και δεκάδες Βρετανοί μονάρχες.","wiki_en":"Westminster Abbey"},{"name":"Μάτι του Λονδίνου","emoji":"🎡","meta":["Ηνωμένο Βασίλειο","τροχός θέασης","άνοιξε το 2000"],"description":"Ο γιγαντιαίος τροχός θέασης στη νότια όχθη του Τάμεση στήθηκε ως προσωρινό θέαμα για την υποδοχή της νέας χιλιετίας, έμεινε όμως ως ένα από τα κύρια αξιοθέατα του Λονδίνου. Μια πλήρης περιστροφή της καμπίνας διαρκεί περίπου μισή ώρα.","fact":"Ο τροχός περιστρέφεται αδιάκοπα και τόσο αργά, που οι επιβάτες μπαίνουν στις καμπίνες εν κινήσει, χωρίς αυτός να σταματήσει.","wiki_en":"London Eye"},{"name":"Καθεδρικός του Αγίου Παύλου","emoji":"⛪","meta":["Ηνωμένο Βασίλειο","καθεδρικός ναός","χτίστηκε το 1675–1710"],"description":"Ο θολωτός αυτός ναός στο Λονδίνο χτίστηκε σε σχέδια του αρχιτέκτονα Κρίστοφερ Ρεν, μετά τη Μεγάλη Πυρκαγιά που κατέστρεψε το προηγούμενο κτίριο. Ο θόλος του παρέμεινε για πολύ καιρό ένα από τα ψηλότερα κατασκευάσματα της πόλης.","fact":"Ο Καθεδρικός του Αγίου Παύλου πέρασε τους βομβαρδισμούς του Λονδίνου στον Β΄ Παγκόσμιο Πόλεμο σχεδόν άθικτος, κάτι που έγινε σύμβολο της αντοχής της πόλης.","wiki_en":"St Paul's Cathedral"},{"name":"Λίμνες Πλίτβιτσε","emoji":"🏞️","meta":["Κροατία","σύστημα λιμνών και καταρρακτών","εθνικό πάρκο από το 1949"],"description":"Δεκαέξι τιρκουάζ λίμνες συνδέονται μεταξύ τους με καταρράκτες και με ξύλινους διαδρόμους, πάνω στους οποίους περνούν οι πεζοπορικές διαδρομές. Το χρώμα του νερού αλλάζει ανάλογα με τη σύσταση των μετάλλων και την ποσότητα των φυκιών.","fact":"Οι λίμνες χωρίζονται από φυσικά φράγματα τραβερτίνης, που μεγαλώνουν από μόνα τους και αλλάζουν σιγά σιγά το σχέδιο των καταρρακτών.","wiki_en":"Plitvice Lakes National Park"},{"name":"Λίμνη Κόμο","emoji":"🛥️","meta":["Ιταλία","λίμνη","παγετώδους προέλευσης"],"description":"Μία από τις βαθύτερες λίμνες της Ευρώπης, στους πρόποδες των Άλπεων, έχει από παλιά αγαπηθεί από την ευρωπαϊκή αριστοκρατία και τους διάσημους για τις βίλες στις γραφικές ακτές της. Το σχήμα της θυμίζει ανεστραμμένο γράμμα «Υ», κάτι που την κάνει ιδιαίτερα αναγνωρίσιμη.","fact":"Οι βίλες στις ακτές του Κόμο έγιναν πολλές φορές σκηνικά μεγάλων ταινιών — από τον «Πόλεμο των Άστρων» μέχρι τις ταινίες του Τζέιμς Μποντ.","wiki_en":"Lake Como"},{"name":"Ερυθρά Θάλασσα","emoji":"🐠","meta":["ανάμεσα στην Αφρική και την Ασία","θάλασσα","σχηματίζεται περίπου 30 εκατ. χρόνια"],"description":"Μία από τις πιο δημοφιλείς περιοχές καταδύσεων στον κόσμο, χάρη στο ζεστό και διάφανο νερό και τους πλούσιους κοραλλιογενείς υφάλους. Η θάλασσα δημιουργήθηκε από τη διάρρηξη της αφρικανικής και της αραβικής λιθοσφαιρικής πλάκας.","fact":"Η ονομασία «Ερυθρά Θάλασσα» μπορεί να σχετίζεται με την εποχική άνθιση φυκιών, που δίνουν στο νερό μια κοκκινωπή απόχρωση.","wiki_en":"Red Sea"},{"name":"Βόρειο Σέλας","emoji":"🌌","meta":["πολικές περιοχές","φυσικό φωτεινό φαινόμενο","παρατηρείται από την αρχαιότητα"],"description":"Ο ουρανός φωτίζεται όταν φορτισμένα σωματίδια του ηλιακού ανέμου συγκρούονται με την ατμόσφαιρα της Γης κοντά στους πόλους. Το χρώμα εξαρτάται από το ποια αέρια της ατμόσφαιρας συμμετέχουν στη σύγκρουση — συνήθως βγαίνουν πράσινες και ροδαλές αποχρώσεις.","fact":"Το πράσινο χρώμα του βόρειου σέλατος προκύπτει από τη φωταύγεια των ατόμων οξυγόνου σε συγκεκριμένο ύψος της ατμόσφαιρας.","wiki_en":"Aurora"},{"name":"Γραμμές της Νάσκα","emoji":"📐","meta":["Περού","γεώγλυφα","φτιάχτηκαν πριν από περίπου 2.000 χρόνια"],"description":"Γιγαντιαίες μορφές ζώων και γεωμετρικών σχημάτων, χαραγμένες σε ένα υψίπεδο της ερήμου του Περού, διακρίνονται ολόκληρες μόνο από ψηλά. Ο προορισμός τους παραμένει μέχρι σήμερα αντικείμενο διαφωνίας μεταξύ των ερευνητών.","fact":"Ολόκληρα τα σχέδια αυτά τα είδαν μόλις τον 20ό αιώνα, όταν άρχισαν να περνούν αεροπλάνα πάνω από το υψίπεδο.","wiki_en":"Nazca Lines"},{"name":"Λίμνη Τιτικάκα","emoji":"🛶","meta":["Περού και Βολιβία","ορεινή λίμνη","από τις αρχαιότερες λίμνες"],"description":"Μία από τις πιο ψηλές πλωτές λίμνες στον κόσμο βρίσκεται στα σύνορα του Περού και της Βολιβίας, μέσα στις Άνδεις. Στα πλωτά νησιά της, πλεγμένα από καλάμια, ζουν ακόμη σήμερα άνθρωποι του λαού Ούρου.","fact":"Ως προς τον όγκο του νερού, η Τιτικάκα είναι η μεγαλύτερη λίμνη της Νότιας Αμερικής, και οι ακτές της βρίσκονται σε ύψος περίπου τεσσάρων χιλιομέτρων.","wiki_en":"Lake Titicaca"},{"name":"Παταγονία","emoji":"🏔️","meta":["Αργεντινή και Χιλή","φυσική περιοχή","διαμορφωνόταν εκατομμύρια χρόνια"],"description":"Εκτεταμένη και αραιοκατοικημένη περιοχή στον νότο της Νότιας Αμερικής, γνωστή για τους παγετώνες, τις αιχμηρές γρανιτένιες κορυφές όπως ο Φιτς Ρόι και τους σκληρούς ανέμους των στεπών. Τα εθνικά πάρκα της τραβούν ορειβάτες και πεζοπόρους από όλο τον κόσμο.","fact":"Ο παγετώνας Περίτο Μορένο στην αργεντίνικη Παταγονία είναι ένας από τους λίγους στον κόσμο που δεν υποχωρεί, αλλά κατά τόπους μεγαλώνει.","wiki_en":"Patagonia"},{"name":"Χρυσός Ναός του Αμριτσάρ","emoji":"🛕","meta":["Ινδία","κεντρικός ναός των Σιχ","χτίστηκε στα τέλη του 16ου αιώνα"],"description":"Το κύριο ιερό του σιχισμού στέκει στη μέση μιας τεχνητής λίμνης και είναι επενδυμένο με φύλλα χρυσού — από εκεί πήρε και το όνομά του. Στον ναό ταΐζουν δωρεάν δεκάδες χιλιάδες προσκυνητές και επισκέπτες κάθε πίστης, κάθε μέρα.","fact":"Ο ναός έχει τέσσερις εισόδους από διαφορετικές πλευρές — ως σημάδι ότι είναι ανοιχτός σε ανθρώπους κάθε καταγωγής και κάθε πίστης.","wiki_en":"Golden Temple"},{"name":"Γάγγης","emoji":"🕉️","meta":["Ινδία","ιερός ποταμός","από τους αρχαιότερους λατρευόμενους ποταμούς"],"description":"Ο ποταμός ξεκινά από τα Ιμαλάια και θεωρείται ιερός στον ινδουισμό: εκατομμύρια προσκυνητές κάνουν κάθε χρόνο τελετουργικά λουτρά στα νερά του. Στις όχθες του βρίσκονται αρχαίες πόλεις, ανάμεσά τους και το Βαρανάσι, μία από τις παλαιότερες συνεχώς κατοικημένες πόλεις στον κόσμο.","fact":"Μαζί με τον Βραχμαπούτρα, ο Γάγγης σχηματίζει το μεγαλύτερο δέλτα ποταμού στον κόσμο, γεμάτο με τα μαγγρόβια δάση των Σουντάρμπανς.","wiki_en":"Ganges"},{"name":"Ιμαλάια","emoji":"🏔️","meta":["Ασία","οροσειρά","σχηματίζονται περίπου 50 εκατ. χρόνια"],"description":"Η μεγαλύτερη οροσειρά του πλανήτη δημιουργήθηκε από τη σύγκρουση της ινδικής και της ευρασιατικής λιθοσφαιρικής πλάκας και συνεχίζει να μεγαλώνει. Εδώ βρίσκονται οι περισσότερες κορυφές των οκτώ χιλιάδων μέτρων της Γης, ανάμεσά τους και το Έβερεστ.","fact":"Και οι δεκατέσσερις κορυφές του κόσμου με ύψος πάνω από οκτώ χιλιάδες μέτρα βρίσκονται στα Ιμαλάια και στο γειτονικό Καρακορούμ.","wiki_en":"Himalayas"},{"name":"Σαχάρα","emoji":"🏜️","meta":["Βόρεια Αφρική","η μεγαλύτερη θερμή έρημος","έγινε έρημος πριν από χιλιάδες χρόνια"],"description":"Η μεγαλύτερη θερμή έρημος του κόσμου εκτείνεται σε πάνω από δώδεκα αφρικανικές χώρες, παρόλο που πριν από χιλιάδες χρόνια στη θέση της υπήρχε σαβάνα με ποτάμια και λίμνες. Σήμερα συναντάς εδώ και απέραντους αμμόλοφους και πετρώδη υψίπεδα.","fact":"Τη μέρα στη Σαχάρα η θερμοκρασία ξεπερνά τους 45 βαθμούς, ενώ τη νύχτα μπορεί να πέσει σχεδόν στο μηδέν.","wiki_en":"Sahara"},{"name":"Κάστρο Χιμέτζι","emoji":"🏯","meta":["Ιαπωνία","κάστρο","ξαναχτίστηκε στις αρχές του 17ου αιώνα"],"description":"Το κατάλευκο αυτό κάστρο το λένε «κάστρο του λευκού ερωδιού» για τις κομψές καμπυλωτές στέγες του, που θυμίζουν φτερά πουλιού. Είναι ένα από τα λίγα ιαπωνικά κάστρα που διατήρησαν τα αυθεντικά ξύλινα κτίσματά τους και όχι σύγχρονο αντίγραφο από σκυρόδεμα.","fact":"Το Χιμέτζι είναι ένα από τα λίγα ιαπωνικά κάστρα που δεν καταστράφηκαν ποτέ από πόλεμο ή πυρκαγιά σε όλη την ιστορία τους.","wiki_en":"Himeji Castle"},{"name":"Άλσος Αρασιγιάμα","emoji":"🎋","meta":["Ιαπωνία","άλσος μπαμπού","δημοφιλές από την περίοδο Χεϊάν"],"description":"Πυκνές συστάδες ψηλού μπαμπού στα περίχωρα του Κιότο σχηματίζουν έναν σκιερό πράσινο διάδρομο, όπου οι βλαστοί λικνίζονται και θροΐζουν στον άνεμο πάνω από τα κεφάλια των επισκεπτών. Το μέρος ενέπνεε από παλιά Ιάπωνες ποιητές και ζωγράφους.","fact":"Οι βλαστοί του μπαμπού στο άλσος Αρασιγιάμα μπορούν να ψηλώσουν δεκάδες εκατοστά μέσα σε ένα μόνο εικοσιτετράωρο.","wiki_en":"Arashiyama"},{"name":"Πύργος του Τόκιο","emoji":"🗼","meta":["Ιαπωνία","τηλεοπτικός πύργος","χτίστηκε το 1958"],"description":"Ο κόκκινο-λευκός πύργος στο Τόκιο σχεδιάστηκε κατά το πρότυπο του Άιφελ, βγήκε όμως ψηλότερος από το γαλλικό του πρότυπο. Για πολύ καιρό ήταν ο κύριος τηλεοπτικός πυλώνας της πόλης, σήμερα δε παραμένει δημοφιλής εξέδρα θέασης και σύμβολο της μεταπολεμικής ανάκαμψης της Ιαπωνίας.","fact":"Το ριγέ βάψιμο του πύργου, με τη χαρακτηριστική πορτοκαλί απόχρωση, ανανεώνεται στο χέρι περίπου κάθε πέντε χρόνια.","wiki_en":"Tokyo Tower"},{"name":"Διάβαση της Σιμπούγια","emoji":"🚦","meta":["Ιαπωνία","αστική διάβαση","γνωστή από τα μέσα του 20ού αιώνα"],"description":"Μία από τις πιο πολυσύχναστες διαβάσεις πεζών στον κόσμο, στο Τόκιο, αφήνει εκατοντάδες ανθρώπους να περάσουν προς όλες τις κατευθύνσεις μαζί, όταν ανάβει ταυτόχρονα πράσινο σε όλα τα φανάρια. Οι γύρω ουρανοξύστες με τις διαφημιστικές οθόνες εντείνουν την αίσθηση της φουτουριστικής μεγαλούπολης.","fact":"Στη διάβαση της Σιμπούγια, στις ώρες αιχμής, μπορούν να περνούν ταυτόχρονα τον δρόμο έως μερικές χιλιάδες άνθρωποι.","wiki_en":"Shibuya Crossing"},{"name":"Βουνά του Γκουϊλίν","emoji":"⛰️","meta":["Κίνα","καρστικά βουνά","διαμορφωνόταν εκατομμύρια χρόνια"],"description":"Οι παράξενοι κωνικοί λόφοι κατά μήκος του ποταμού Λι είναι από ασβεστόλιθο και ενέπνεαν για αιώνες Κινέζους ζωγράφους και ποιητές. Τα τοπία της περιοχής θεωρούνται η κλασική εικόνα της παραδοσιακής κινεζικής ζωγραφικής.","fact":"Το τοπίο του Γκουϊλίν εικονίζεται στο κινεζικό χαρτονόμισμα των είκοσι γιουάν.","wiki_en":"Guilin"},{"name":"Πύλη της Ινδίας","emoji":"🏛️","meta":["Ινδία","θριαμβική αψίδα","χτίστηκε το 1924"],"description":"Η μνημειακή αψίδα στη Βομβάη υψώθηκε στη μνήμη της επίσκεψης του Βρετανού βασιλιά Γεωργίου Ε΄ και έγινε σύμβολο της πόλης στην ακτή της Αραβικής Θάλασσας. Από την ίδια πύλη έφυγαν αργότερα τα τελευταία βρετανικά στρατεύματα, μετά την ανακήρυξη της ανεξαρτησίας της Ινδίας.","fact":"Η αψίδα είναι χτισμένη από κίτρινο βασάλτη και σκυρόδεμα, και στη μορφή της ανακατεύονται ινδικά και ευρωπαϊκά αρχιτεκτονικά μοτίβα.","wiki_en":"Gateway of India"},{"name":"Κόκκινο Οχυρό","emoji":"🏰","meta":["Ινδία","φρούριο","χτίστηκε στα μέσα του 17ου αιώνα"],"description":"Το τεράστιο αυτό φρούριο από κόκκινο αμμόλιθο στο Δελχί ήταν η κύρια κατοικία των Μογγόλων αυτοκρατόρων της Ινδίας. Από εδώ απευθύνεται κάθε χρόνο στο έθνος ο πρωθυπουργός της χώρας, την Ημέρα της Ανεξαρτησίας.","fact":"Το οχυρό πήρε το όνομά του από τα τείχη από κόκκινο αμμόλιθο, που απλώνονται γύρω του για πάνω από δύο χιλιόμετρα.","wiki_en":"Red Fort"},{"name":"Έφεσος","emoji":"🏛️","meta":["Τουρκία","αρχαία πόλη","ιδρύθηκε στην 1η χιλιετία π.Χ."],"description":"Τα ερείπια μιας από τις μεγαλύτερες πόλεις του αρχαίου κόσμου διατηρούν την επιβλητική πρόσοψη της Βιβλιοθήκης του Κέλσου και ένα τεράστιο αρχαίο θέατρο. Η πόλη ήταν κάποτε λιμάνι, βρέθηκε όμως με τον καιρό μακριά από τη θάλασσα, καθώς ο κόλπος γέμισε προσχώσεις.","fact":"Η Βιβλιοθήκη του Κέλσου στην Έφεσο φύλαγε κάποτε χιλιάδες κυλίνδρους και θεωρούνταν μία από τις μεγαλύτερες βιβλιοθήκες του αρχαίου κόσμου.","wiki_en":"Ephesus"},{"name":"Κοιλάδα των Βασιλέων","emoji":"🪦","meta":["Αίγυπτος","νεκρόπολη των φαραώ","σε χρήση τον 16ο–11ο αιώνα π.Χ."],"description":"Το βραχώδες φαράγγι στη δυτική όχθη του Νείλου χρησίμευε ως τόπος ταφής των φαραώ του Νέου Βασιλείου, ανάμεσά τους και ο διάσημος τάφος του Τουταγχαμών. Οι περισσότεροι τάφοι λεηλατήθηκαν ήδη στην αρχαιότητα, αλλά οι ζωγραφιές στους τοίχους τους σώθηκαν έως τις μέρες μας.","fact":"Ο τάφος του Τουταγχαμών στην Κοιλάδα των Βασιλέων βρέθηκε σχεδόν άθικτος από τυμβωρύχους — σπανιότατη περίπτωση για την αιγυπτιακή αρχαιολογία.","wiki_en":"Valley of the Kings"},{"name":"Σαντορίνη","emoji":"🌅","meta":["Ελλάδα","ηφαιστειογενές νησί","η μορφή του προήλθε από έκρηξη"],"description":"Το δρεπανόσχημο νησί στο Αιγαίο πήρε τη μορφή του μετά την καταστροφική έκρηξη του ηφαιστείου στην εποχή του χαλκού, που άλλαξε το σχήμα της στεριάς. Τα κατάλευκα σπιτάκια στο χείλος της καλδέρας και τα ηλιοβασιλέματα πάνω από τη θάλασσα το έκαναν ένα από τα σύμβολα της Ελλάδας.","fact":"Η ισχυρή έκρηξη του ηφαιστείου της Σαντορίνης στην εποχή του χαλκού πιθανότατα επηρέασε την παρακμή του μινωικού πολιτισμού στη γειτονική Κρήτη.","wiki_en":"Santorini"},{"name":"Μετέωρα","emoji":"⛰️","meta":["Ελλάδα","μοναστήρια στους βράχους","τα μοναστήρια ιδρύθηκαν τον 14ο αιώνα"],"description":"Ορθόδοξα μοναστήρια χτισμένα στις κορυφές κατακόρυφων βράχων στην κεντρική Ελλάδα, όπου οι μοναχοί ανέβαιναν για αιώνες με ανεμόσκαλες. Από μακριά τα μοναστήρια δίνουν πράγματι την εντύπωση ότι αιωρούνται στον αέρα, όπως λέει και το όνομά τους.","fact":"Για πολύ καιρό η πρόσβαση στα μοναστήρια των Μετεώρων γινόταν μόνο με δίχτυ κρεμασμένο σε σκοινί ή με ανεμόσκαλες που τραβούσαν πάνω.","wiki_en":"Meteora"},{"name":"Αμαζόνιος","emoji":"🐍","meta":["Νότια Αμερική","ποταμός","διαμορφωνόταν εκατομμύρια χρόνια"],"description":"Ένας από τους μεγαλύτερους ποταμούς στον κόσμο ως προς τον όγκο του νερού που μεταφέρει διασχίζει το μεγαλύτερο τροπικό δάσος του πλανήτη, που φέρει το όνομά του. Στη λεκάνη του ποταμού ζει ένα τεράστιο μέρος όλων των γνωστών ειδών ζώων και φυτών της Γης.","fact":"Ο Αμαζόνιος ρίχνει στον ωκεανό περισσότερο νερό απ' ό,τι οι επόμενοι σε παροχή ποταμοί του κόσμου μαζί.","wiki_en":"Amazon River"},{"name":"Λίμνη Γκάρντα","emoji":"🛥️","meta":["Ιταλία","λίμνη","παγετώδους προέλευσης"],"description":"Η μεγαλύτερη λίμνη της Ιταλίας, στους πρόποδες των Άλπεων, είναι γνωστή για το ήπιο κλίμα, τους ελαιώνες και τους αμπελώνες στις όχθες της. Οι μικρές πόλεις γύρω από τη λίμνη, όπως το Σιρμιόνε, διατήρησαν μεσαιωνικά κάστρα και ρωμαϊκά ερείπια.","fact":"Στη χερσόνησο του Σιρμιόνε, στη λίμνη Γκάρντα, σώζονται τα ερείπια μιας ρωμαϊκής έπαυλης που παραδοσιακά συνδέεται με το όνομα του ποιητή Κάτουλλου.","wiki_en":"Lake Garda"},{"name":"Γέφυρα του Βοσπόρου","emoji":"🌉","meta":["Τουρκία","κρεμαστή γέφυρα","χτίστηκε το 1973"],"description":"Η πρώτη μόνιμη γέφυρα πάνω από τον Βόσπορο ένωσε το ευρωπαϊκό και το ασιατικό τμήμα της Κωνσταντινούπολης και συμβολικά δύο ηπείρους. Με το άνοιγμά της έγινε για πρώτη φορά δυνατό να περάσει κανείς το στενό με αυτοκίνητο και όχι μόνο με φέριμποτ.","fact":"Η κυκλοφορία στη γέφυρα άνοιξε το 1973, για τα πενήντα χρόνια της Τουρκικής Δημοκρατίας.","wiki_en":"Bosphorus Bridge"},{"name":"Μπλε Λιμνοθάλασσα","emoji":"♨️","meta":["Ισλανδία","γεωθερμικό λουτρό","άνοιξε το 1992"],"description":"Λεκάνη με γαλακτώδες γαλάζιο μεταλλικό νερό, που δημιουργήθηκε ως παραπροϊόν της λειτουργίας του γειτονικού γεωθερμικού εργοστασίου. Το ζεστό νερό, πλούσιο σε πυριτία και άλατα, τραβά επισκέπτες όλο τον χρόνο, ακόμη και στην καρδιά του ισλανδικού χειμώνα.","fact":"Η θερμοκρασία του νερού στη λιμνοθάλασσα κρατιέται όλο τον χρόνο γύρω στους 38 βαθμούς, ανεξάρτητα από τον καιρό έξω.","wiki_en":"Blue Lagoon (geothermal spa)"},{"name":"Πάλμ Τζουμέιρα","emoji":"🌴","meta":["ΗΑΕ","τεχνητό νησί","χτίστηκε στη δεκαετία του 2000"],"description":"Το αρχιπέλαγος σε σχήμα φοίνικα δημιουργήθηκε με προσχώσεις στη θάλασσα, στα ανοιχτά του Ντουμπάι, και ξεχωρίζει ακόμη και από το διάστημα χάρη στο χαρακτηριστικό σχήμα του. Στον κορμό και στα «φύλλα» του νησιού βρίσκονται βίλες, ξενοδοχεία και συγκροτήματα κατοικιών.","fact":"Το νησί σχηματίστηκε από εκατομμύρια κυβικά μέτρα άμμου από τον βυθό του κόλπου, ενώ από τα κύματα το προστατεύει ένας εξωτερικός κυματοθραύστης σε σχήμα μισοφέγγαρου.","wiki_en":"Palm Jumeirah"},{"name":"Ντίσνεϊλαντ","emoji":"🎢","meta":["ΗΠΑ","πάρκο ψυχαγωγίας","άνοιξε το 1955"],"description":"Το πρώτο πάρκο της Ντίσνεϊ άνοιξε στην Καλιφόρνια με προσωπική έμπνευση του Γουόλτ Ντίσνεϊ και έγινε πρότυπο για δεκάδες παρόμοια πάρκα σε όλο τον κόσμο. Το κάστρο της Ωραίας Κοιμωμένης στο κέντρο του είναι μια από τις πιο αναγνωρίσιμες σιλουέτες της βιομηχανίας ψυχαγωγίας.","fact":"Στην είσοδο του πάρκου κρέμεται πινακίδα που υπόσχεται στους επισκέπτες ότι αφήνουν πίσω τη σημερινή μέρα και μπαίνουν σε έναν κόσμο του παρελθόντος, του μέλλοντος και της φαντασίας.","wiki_en":"Disneyland"},{"name":"Πανεπιστήμιο της Οξφόρδης","emoji":"🎓","meta":["Ηνωμένο Βασίλειο","πανεπιστήμιο","διδασκαλία από τον 11ο αιώνα"],"description":"Το αρχαιότερο πανεπιστήμιο του αγγλόφωνου κόσμου αποτελείται από δεκάδες αυτοτελή κολέγια, σκορπισμένα στο ιστορικό κέντρο της πόλης. Ανάμεσα στους αποφοίτους του βρίσκονται πολλοί Βρετανοί πρωθυπουργοί και βραβευμένοι με Νόμπελ.","fact":"Η Οξφόρδη είναι παλαιότερη από το κράτος των Αζτέκων: εδώ γίνονταν μαθήματα πριν ακόμη ιδρυθεί η Τενοτστιτλάν.","wiki_en":"University of Oxford"},{"name":"Πανεπιστήμιο του Κέιμπριτζ","emoji":"📚","meta":["Ηνωμένο Βασίλειο","πανεπιστήμιο","ιδρύθηκε το 1209"],"description":"Το πανεπιστήμιο δημιουργήθηκε αφού μέρος των λογίων εγκατέλειψε την Οξφόρδη μετά από σύγκρουση με τους κατοίκους της, και με τον καιρό έγινε ο κύριος αντίπαλός της. Τα κολέγια κατά μήκος του ποταμού Καμ, με τα πράσινα γκαζόν και την παράδοση της βαρκάδας με κοντάρι, δίνουν στην πόλη τη μοναδική της όψη.","fact":"Στο Κέιμπριτζ σπούδασαν ο Ισαάκ Νεύτων και ο Κάρολος Δαρβίνος, ενώ συνολικά με το πανεπιστήμιο συνδέονται δεκάδες βραβευμένοι με Νόμπελ.","wiki_en":"University of Cambridge"},{"name":"Μουσεία του Βατικανού","emoji":"🖼️","meta":["Βατικανό","μουσειακό συγκρότημα","ιδρύθηκαν στις αρχές του 16ου αιώνα"],"description":"Ένα από τα μεγαλύτερα μουσειακά συγκροτήματα στον κόσμο συγκεντρώνει τις συλλογές των παπών επί αιώνες — από αρχαία γλυπτά έως πίνακες της Αναγέννησης. Η διαδρομή στις αίθουσες καταλήγει παραδοσιακά στην Καπέλα Σιξτίνα, με τις τοιχογραφίες του Μιχαήλ Άγγελου.","fact":"Οι αίθουσες των μουσείων απλώνονται για αρκετά χιλιόμετρα, και είναι πρακτικά αδύνατο να τις δει κανείς όλες σε μία επίσκεψη.","wiki_en":"Vatican Museums"},{"name":"Καπέλα Σιξτίνα","emoji":"🎨","meta":["Βατικανό","παρεκκλήσι","χτίστηκε στα τέλη του 15ου αιώνα"],"description":"Το ιδιωτικό παρεκκλήσι των παπών είναι διάσημο για την οροφή του Μιχαήλ Άγγελου με τη δημιουργία του κόσμου και για την τοιχογραφία της «Δευτέρας Παρουσίας» στον τοίχο του ιερού. Εδώ γίνεται και το κονκλάβιο, στο οποίο οι καρδινάλιοι εκλέγουν τον νέο πάπα.","fact":"Σε αντίθεση με τον διαδεδομένο μύθο, ο Μιχαήλ Άγγελος δεν ζωγράφιζε την οροφή ξαπλωμένος ανάσκελα, αλλά όρθιος πάνω σε σκαλωσιές, με το κεφάλι γερμένο πίσω.","wiki_en":"Sistine Chapel"},{"name":"Πινακοθήκη Ουφίτσι","emoji":"🖼️","meta":["Ιταλία","μουσείο τέχνης","άνοιξε για το κοινό το 1765"],"description":"Ένα από τα παλαιότερα μουσεία τέχνης της Ευρώπης, στη Φλωρεντία, φυλάσσει μια από τις πλουσιότερες συλλογές ζωγραφικής της ιταλικής Αναγέννησης, με έργα του Μποτιτσέλι και του Λεονάρντο ντα Βίντσι. Το κτίριο χτίστηκε αρχικά ως διοικητικά γραφεία των ηγεμόνων της Τοσκάνης.","fact":"Στα Ουφίτσι φυλάσσεται η «Γέννηση της Αφροδίτης» του Μποτιτσέλι — ένας από τους πιο αναγνωρίσιμους πίνακες της Αναγέννησης.","wiki_en":"Uffizi"},{"name":"Γέφυρα Ριάλτο","emoji":"🌉","meta":["Ιταλία","γέφυρα","χτίστηκε στα τέλη του 16ου αιώνα"],"description":"Η παλαιότερη γέφυρα του Μεγάλου Καναλιού στη Βενετία ήταν για πολύ καιρό ο μόνος τρόπος να περάσει κανείς το κανάλι με τα πόδια. Η πέτρινη καμάρα της, με σειρές μαγαζάκια στα πλάγια, σχεδιάστηκε αφού κατέρρευσαν αρκετές προηγούμενες ξύλινες γέφυρες.","fact":"Την πέτρινη γέφυρα την έχτισαν σε σχέδια του αρχιτέκτονα Αντόνιο ντα Πόντε, του οποίου το επώνυμο σημαίνει κατά λέξη «της γέφυρας».","wiki_en":"Rialto Bridge"},{"name":"Μεγάλο Κανάλι","emoji":"🚤","meta":["Ιταλία","το κύριο κανάλι της Βενετίας","αρτηρία της πόλης από τον Μεσαίωνα"],"description":"Η κύρια υδάτινη αρτηρία της Βενετίας διαγράφει μια καμπύλη μέσα από όλη την πόλη σε σχήμα ανεστραμμένου «S», και στις όχθες της στέκουν πολυτελή παλάτια διαφορετικών εποχών. Αντί για αυτοκίνητα, στο κανάλι κινούνται βαρκάκια, βαπορέτα και γόνδολες.","fact":"Όλο το μήκος του Μεγάλου Καναλιού το διασχίζουν μόνο τέσσερις γέφυρες, γι' αυτό και οι Βενετοί περνούν συχνά στην άλλη όχθη με τα βαρκάκια τραγκέτο.","wiki_en":"Grand Canal (Venice)"},{"name":"Ακρόπολη των Αθηνών","emoji":"🏛️","meta":["Ελλάδα","συγκρότημα αρχαίων ναών","ο Παρθενώνας — 5ος αιώνας π.Χ."],"description":"Ο βραχώδης λόφος στο κέντρο της Αθήνας στεφανώνεται από τον Παρθενώνα, τον ναό της θεάς Αθηνάς, που θεωρείται η κορύφωση της κλασικής ελληνικής αρχιτεκτονικής. Το συγκρότημα πέρασε πολέμους, εκρήξεις και αιώνες διάβρωσης, παραμένει όμως σύμβολο του αρχαίου πολιτισμού.","fact":"Μέρος των γλυπτών της ζωφόρου του Παρθενώνα, γνωστά ως Μάρμαρα του Έλγιν, βρίσκεται στο Βρετανικό Μουσείο του Λονδίνου και όχι στην Αθήνα.","wiki_en":"Acropolis of Athens"},{"name":"Δελφοί","emoji":"🏛️","meta":["Ελλάδα","αρχαίο ιερό","λειτουργούσε από τον 8ο αιώνα π.Χ."],"description":"Το ιερό στην πλαγιά του Παρνασσού θεωρούνταν από τους αρχαίους Έλληνες «ομφαλός της γης» και ήταν η έδρα του διάσημου μαντείου των Δελφών. Ηγεμόνες και στρατηγοί από όλη την Ελλάδα έρχονταν εδώ για χρησμούς, πριν πάρουν σημαντικές αποφάσεις.","fact":"Κατά την παράδοση, τους χρησμούς του μαντείου των Δελφών τους έδινε η ιέρεια Πυθία, που εισέπνεε αναθυμιάσεις από ένα χάσμα του βράχου.","wiki_en":"Delphi"},{"name":"Κολοσσός της Ρόδου","emoji":"🗿","meta":["Ελλάδα","γιγάντιο άγαλμα","χτίστηκε γύρω στο 280 π.Χ."],"description":"Ένα από τα επτά θαύματα του αρχαίου κόσμου — ένα τεράστιο χάλκινο άγαλμα του θεού Ήλιου — στεκόταν στην είσοδο του λιμανιού της Ρόδου. Μερικές δεκαετίες μετά την ανέγερσή του, το άγαλμα γκρεμίστηκε σε σεισμό και δεν ξαναστήθηκε ποτέ.","fact":"Παρά τα δημοφιλή χαρακτικά, το άγαλμα μάλλον δεν στεκόταν με τα πόδια ανοιχτά πάνω από την είσοδο του λιμανιού — αυτό είναι επινόηση μεταγενέστερων εποχών.","wiki_en":"Colossus of Rhodes"},{"name":"Φάρος της Αλεξάνδρειας","emoji":"🗼","meta":["Αίγυπτος","φάρος","χτίστηκε τον 3ο αιώνα π.Χ."],"description":"Ένα από τα επτά θαύματα του αρχαίου κόσμου υψωνόταν στο νησί Φάρος, στην είσοδο του λιμανιού της Αλεξάνδρειας, και για αιώνες υπήρξε πρότυπο για τους φάρους όλης της Μεσογείου. Το κτίσμα καταστράφηκε σταδιακά από σεισμούς στον Μεσαίωνα.","fact":"Ο φάρος ήταν ένα από τα ψηλότερα κτίσματα της εποχής του και για πολλούς αιώνες παρέμεινε ανάμεσα στα ψηλότερα κατασκευάσματα του ανθρώπου.","wiki_en":"Lighthouse of Alexandria"},{"name":"Κρεμαστοί Κήποι της Βαβυλώνας","emoji":"🌿","meta":["Βαβυλώνα, σημ. Ιράκ","μυθικοί κήποι","πιθανώς 6ος αιώνας π.Χ."],"description":"Ένα από τα επτά θαύματα του αρχαίου κόσμου, που οι αρχαίοι συγγραφείς περιγράφουν ως κλιμακωτές βεράντες με πλούσιο πράσινο μέσα στην ξηρή Μεσοποταμία. Οι αρχαιολόγοι διαφωνούν ακόμη αν οι κήποι υπήρξαν στην πραγματικότητα και πού βρίσκονταν.","fact":"Σε αντίθεση με τα άλλα θαύματα του κόσμου, η ακριβής θέση και η ίδια η ύπαρξη των Κρεμαστών Κήπων δεν έχουν επιβεβαιωθεί αρχαιολογικά.","wiki_en":"Hanging Gardens of Babylon"},{"name":"Μαυσωλείο της Αλικαρνασσού","emoji":"🪦","meta":["Τουρκία","μνημειακός τάφος","χτίστηκε τον 4ο αιώνα π.Χ."],"description":"Ένα από τα επτά θαύματα του αρχαίου κόσμου — ο μνημειακός τάφος του ηγεμόνα Μαυσώλου — έδωσε τη λέξη «μαυσωλείο» για κατασκευές αυτού του τύπου. Το κτίσμα στεκόταν πάνω από χίλια πεντακόσια χρόνια, προτού το γκρεμίσουν σεισμοί.","fact":"Οι λίθοι του κατεστραμμένου τάφου χρησιμοποιήθηκαν αργότερα για το κάστρο των ιπποτών στο Μπόντρουμ, που στέκει σε αυτή την ακτή ακόμη σήμερα.","wiki_en":"Mausoleum at Halicarnassus"},{"name":"Άγαλμα του Δία στην Ολυμπία","emoji":"🗿","meta":["Ελλάδα","γιγάντιο άγαλμα","φτιάχτηκε τον 5ο αιώνα π.Χ."],"description":"Ένα από τα επτά θαύματα του αρχαίου κόσμου — ένα πελώριο άγαλμα του ύπατου θεού των Ελλήνων, καλυμμένο με χρυσό και ελεφαντόδοντο — στεκόταν στον ναό, στον τόπο των αρχαίων Ολυμπιακών Αγώνων. Το πρωτότυπο δεν σώθηκε και η τύχη του αγάλματος μετά την αρχαιότητα παραμένει ασαφής.","fact":"Το άγαλμα του Δία στην Ολυμπία το έφτιαξε ο γλύπτης Φειδίας, που είχε προηγουμένως επιβλέψει τα γλυπτά του Παρθενώνα στην Αθήνα.","wiki_en":"Statue of Zeus at Olympia"},{"name":"Ναός της Αρτέμιδος στην Έφεσο","emoji":"🏛️","meta":["Τουρκία","ναός της θεάς Αρτέμιδος","χτίστηκε τον 6ο αιώνα π.Χ."],"description":"Ένα από τα επτά θαύματα του αρχαίου κόσμου θεωρούνταν ένας από τους μεγαλύτερους ναούς της αρχαιότητας και ξαναχτίστηκε αρκετές φορές μετά από πυρκαγιές και καταστροφές. Από το άλλοτε μεγαλοπρεπές ιερό έχει φτάσει στις μέρες μας μόνο ένας αναστηλωμένος κίονας.","fact":"Κατά την παράδοση, τον ναό τον έκαψε κάποιος ονόματι Ηρόστρατος — μόνο και μόνο για να μείνει για πάντα το όνομά του στη μνήμη.","wiki_en":"Temple of Artemis"},{"name":"Κάστρο Ουίνδσορ","emoji":"🏰","meta":["Ηνωμένο Βασίλειο","βασιλική κατοικία","ιδρύθηκε τον 11ο αιώνα"],"description":"Ένα από τα παλαιότερα και μεγαλύτερα κατοικούμενα κάστρα στον κόσμο υπηρετεί ως μία από τις επίσημες κατοικίες των Βρετανών μοναρχών εδώ και σχεδόν χίλια χρόνια. Εδώ είναι θαμμένη και η βασίλισσα Ελισάβετ Β΄.","fact":"Το επώνυμο Ουίνδσορ το πήρε η βρετανική βασιλική οικογένεια το 1917, ακριβώς από το όνομα αυτού του κάστρου.","wiki_en":"Windsor Castle"},{"name":"Πυραμίδα του Λούβρου","emoji":"🔺","meta":["Γαλλία","γυάλινη πυραμίδα","χτίστηκε το 1989"],"description":"Η πυραμίδα από γυαλί και μέταλλο στην εσωτερική αυλή του Λούβρου στο Παρίσι χρησιμεύει ως η κύρια είσοδος του μουσείου και κάποτε προκάλεσε έντονες διαμάχες με τη σύγχρονη μορφή της δίπλα στο ιστορικό παλάτι. Σήμερα έχει γίνει η ίδια ένα από τα αναγνωρίσιμα σύμβολα του Παρισιού.","fact":"Την πυραμίδα σχεδίασε ο Αμερικανός αρχιτέκτονας κινεζικής καταγωγής Ιέο Μινγκ Πέι, και το ύψος της είναι λίγο πάνω από είκοσι μέτρα.","wiki_en":"Louvre Pyramid"},{"name":"Παλάτι του Βεστμίνστερ","emoji":"🏛️","meta":["Ηνωμένο Βασίλειο","κτίριο του κοινοβουλίου","το σημερινό κτίριο — 19ος αιώνας"],"description":"Η έδρα του βρετανικού κοινοβουλίου στην όχθη του Τάμεση ξαναχτίστηκε σχεδόν ολόκληρη σε νεογοτθικό ύφος μετά από μεγάλη πυρκαγιά του 19ου αιώνα. Ο πύργος με την καμπάνα Μπιγκ Μπεν, που τυπικά είναι μόνο ένα τμήμα του κτιρίου, έγινε ένα από τα κύρια σύμβολα του Λονδίνου.","fact":"Το διάσημο «Μπιγκ Μπεν» είναι το όνομα της καμπάνας στον πύργο του Παλατιού του Βεστμίνστερ και όχι του πύργου, όπως συνήθως νομίζουν.","wiki_en":"Palace of Westminster"}];
